export default JSON.parse('{"work":{"id":"art-of-war","schoolId":"military","title":"《孫子兵法》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["art-of-war_ch-1","art-of-war_ch-2","art-of-war_ch-3","art-of-war_ch-4","art-of-war_ch-5","art-of-war_ch-6","art-of-war_ch-7","art-of-war_ch-8","art-of-war_ch-9","art-of-war_ch-10","art-of-war_ch-11","art-of-war_ch-12","art-of-war_ch-13"],"totalChars":7371,"subtitle":"孫武"},"chapters":[{"id":"art-of-war_ch-1","workId":"art-of-war","order":1,"title":"始計","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-1_p-1","art-of-war_ch-1_p-2","art-of-war_ch-1_p-3","art-of-war_ch-1_p-4","art-of-war_ch-1_p-5","art-of-war_ch-1_p-6","art-of-war_ch-1_p-7"],"tags":[]},{"id":"art-of-war_ch-2","workId":"art-of-war","order":2,"title":"作戰","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-2_p-1","art-of-war_ch-2_p-2","art-of-war_ch-2_p-3","art-of-war_ch-2_p-4","art-of-war_ch-2_p-5"],"tags":[]},{"id":"art-of-war_ch-3","workId":"art-of-war","order":3,"title":"謀攻","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-3_p-1","art-of-war_ch-3_p-2","art-of-war_ch-3_p-3","art-of-war_ch-3_p-4","art-of-war_ch-3_p-5","art-of-war_ch-3_p-6"],"tags":[]},{"id":"art-of-war_ch-4","workId":"art-of-war","order":4,"title":"軍形","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-4_p-1","art-of-war_ch-4_p-2","art-of-war_ch-4_p-3","art-of-war_ch-4_p-4"],"tags":[]},{"id":"art-of-war_ch-5","workId":"art-of-war","order":5,"title":"兵勢","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-5_p-1","art-of-war_ch-5_p-2","art-of-war_ch-5_p-3","art-of-war_ch-5_p-4","art-of-war_ch-5_p-5"],"tags":[]},{"id":"art-of-war_ch-6","workId":"art-of-war","order":6,"title":"虛實","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-6_p-1","art-of-war_ch-6_p-2","art-of-war_ch-6_p-3","art-of-war_ch-6_p-4","art-of-war_ch-6_p-5","art-of-war_ch-6_p-6","art-of-war_ch-6_p-7"],"tags":[]},{"id":"art-of-war_ch-7","workId":"art-of-war","order":7,"title":"軍爭","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-7_p-1","art-of-war_ch-7_p-2","art-of-war_ch-7_p-3","art-of-war_ch-7_p-4","art-of-war_ch-7_p-5","art-of-war_ch-7_p-6"],"tags":[]},{"id":"art-of-war_ch-8","workId":"art-of-war","order":8,"title":"九變","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-8_p-1","art-of-war_ch-8_p-2","art-of-war_ch-8_p-3","art-of-war_ch-8_p-4"],"tags":[]},{"id":"art-of-war_ch-9","workId":"art-of-war","order":9,"title":"行軍","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-9_p-1","art-of-war_ch-9_p-2","art-of-war_ch-9_p-3","art-of-war_ch-9_p-4","art-of-war_ch-9_p-5"],"tags":[]},{"id":"art-of-war_ch-10","workId":"art-of-war","order":10,"title":"地形","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-10_p-1","art-of-war_ch-10_p-2","art-of-war_ch-10_p-3","art-of-war_ch-10_p-4","art-of-war_ch-10_p-5"],"tags":[]},{"id":"art-of-war_ch-11","workId":"art-of-war","order":11,"title":"九地","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-11_p-1","art-of-war_ch-11_p-2","art-of-war_ch-11_p-3","art-of-war_ch-11_p-4","art-of-war_ch-11_p-5","art-of-war_ch-11_p-6","art-of-war_ch-11_p-7","art-of-war_ch-11_p-8"],"tags":[]},{"id":"art-of-war_ch-12","workId":"art-of-war","order":12,"title":"火攻","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-12_p-1","art-of-war_ch-12_p-2","art-of-war_ch-12_p-3"],"tags":[]},{"id":"art-of-war_ch-13","workId":"art-of-war","order":13,"title":"用間","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-13_p-1","art-of-war_ch-13_p-2","art-of-war_ch-13_p-3","art-of-war_ch-13_p-4","art-of-war_ch-13_p-5"],"tags":[]}],"passages":[{"id":"art-of-war_ch-1_p-1","chapterId":"art-of-war_ch-1","order":1,"canonicalText":"孫子曰：兵者，國之大事，死生之地，存亡之道，不可不察也。","sentenceIds":["art-of-war_ch-1_p-1_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：兵者，國之大事，死生之地，存亡之道，不可不察也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段為《孫子兵法》全書開篇宗義，指出戰爭乃「國之大事，死生之地，存亡之道」。\\n【詞義與名物】1. 兵者：軍事與戰爭。2. 死生之地：決定人民生死存亡的戰場。3. 察：審慎考察與研究。\\n【思想與篇章】展現了先秦兵家重戰而又慎戰的戰略智慧，打破盲目用兵，將軍事提升至國家戰略高度。"}},{"id":"art-of-war_ch-1_p-2","chapterId":"art-of-war_ch-1","order":2,"canonicalText":"故經之以五事，校之以計，而索其情，一曰道，二曰天，三曰地，四曰將，五曰法。","sentenceIds":["art-of-war_ch-1_p-2_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故經之以五事，校之以計，而索其情，一說：道，二說：天，三說：地，四說：將，五說：法。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段延續慎戰觀念，提出決定戰爭勝負的五大核心要素，即著名的「五事」。\\n【詞義與名物】\\n經：作為綱領、準則。校：比較。索其情：探求真實情況。道：指君民同心同德的政治基礎。天：陰陽寒暑等自然氣候。地：地形險阻與距離遠近。將：將領的智、信、仁、勇、嚴。法：軍隊的編制、制度與軍需管理。\\n【兵家戰略】\\n「五事」構成了全面評估戰爭潛力的框架。孫子將「道」（政治人心）置於首位，顯示出他深刻認識到戰爭不僅是軍事力量的碰撞，更是政治與人心的較量。"}},{"id":"art-of-war_ch-1_p-3","chapterId":"art-of-war_ch-1","order":3,"canonicalText":"道者，令民與上同意也，可與之死，可與之生，而不畏危。天者，陰陽，寒暑，時制也。地者，遠近，險易，廣狹，死生也。將者，智，信，仁，勇，嚴也。法者，曲制，官道，主用也。凡此五者，將莫不聞，知之者勝，不知者不勝。","sentenceIds":["art-of-war_ch-1_p-3_s-1","art-of-war_ch-1_p-3_s-2","art-of-war_ch-1_p-3_s-3","art-of-war_ch-1_p-3_s-4","art-of-war_ch-1_p-3_s-5","art-of-war_ch-1_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"道者，令民與上同意也，可與之死，可與之生，而不畏危；天者，陰陽，寒暑，時制也；地者，遠近，險易，廣狹，死生也；將者，智，信，仁，勇，嚴也；法者，曲制，官道，主用也；凡此五者，將莫不聞，知之者勝，不知者不勝。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】孫子詳細定義「道、天、地、將、法」的內涵，並提出「將帥五德」（智信仁勇嚴）。\\n【詞義與名物】1. 同意：意志與利益高度一致。2. 智信仁勇嚴：合格將帥必備的五大品德。3. 曲制：軍隊各級組織與營伍編制。\\n【思想與篇章】說明勝負取決於政治政治動員、天時地理與優秀將領制度，是孫子戰略學派的思想精華。"}},{"id":"art-of-war_ch-1_p-4","chapterId":"art-of-war_ch-1","order":4,"canonicalText":"故校之以計，而索其情。曰：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士卒孰練，賞罰孰明，吾以此知勝負矣。將聽吾計，用之必勝，留之；將不聽吾計，用之必敗，去之。","sentenceIds":["art-of-war_ch-1_p-4_s-1","art-of-war_ch-1_p-4_s-2","art-of-war_ch-1_p-4_s-3","art-of-war_ch-1_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故校之以計，而索其情；說：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士去世孰練，賞罰孰明，吾以此知勝負矣；將聽吾計，用之必勝，留之；將不聽吾計，用之必敗，去之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段提出「七計」，是「五事」的具體化，作為戰前評估敵我雙方實力的量化指標。\\n【詞義與名物】\\n主孰有道：哪方君主更得民心。將孰有能：哪方將領更有才幹。法令孰行：軍令是否暢通。練：訓練有素。明：公平嚴明。\\n【兵家戰略】\\n透過七個方面的細緻比較，將領可以客觀預測戰爭走向（「知勝負」）。這體現了孫子「先勝而後求戰」的戰略思想，同時強調了戰略計畫的權威性與執行力。"}},{"id":"art-of-war_ch-1_p-5","chapterId":"art-of-war_ch-1","order":5,"canonicalText":"計利以聽，乃為之勢，以佐其外；勢者，因利而制權也。","sentenceIds":["art-of-war_ch-1_p-5_s-1","art-of-war_ch-1_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"分析了有利的條件並被採納後，就要營造有利的態勢，作為外部的輔助手段；所謂態勢，就是根據對我方有利的條件而靈活應變、掌握主動權。","analysis":"【主題與背景】\\n本段探討「勢」的概念，說明在客觀條件（五事七計）具備後，如何發揮主觀能動性來創造戰場優勢。\\n【詞義與名物】\\n勢：戰略態勢、軍事優勢。因利而制權：根據有利的條件，靈活變通以控制局面。「權」指權變、應變。\\n【兵家戰略】\\n孫子極度重視「勢」。靜態的實力對比（計）必須轉化為動態的戰場優勢（勢）。「因利而制權」指出將領必須具備敏銳的洞察力與極高的指揮藝術，隨時根據形勢變化調整部署，牢牢掌握戰場主動。"}},{"id":"art-of-war_ch-1_p-6","chapterId":"art-of-war_ch-1","order":6,"canonicalText":"兵者，詭道也。故能而示之不能，用而示之不用，近而示之遠，遠而示之近。利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之。攻其無備，出其不意，此兵家之勝，不可先傳也。","sentenceIds":["art-of-war_ch-1_p-6_s-1","art-of-war_ch-1_p-6_s-2","art-of-war_ch-1_p-6_s-3","art-of-war_ch-1_p-6_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"兵者，詭道也；故能而示之不能，用而示之不用，近而示之遠，遠而示之近；利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之；攻其無備，出其不意，此兵家之勝，不可先傳也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《孫子兵法》〈始計〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「兵者，詭道也」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"art-of-war_ch-1_p-7","chapterId":"art-of-war_ch-1","order":7,"canonicalText":"夫未戰而廟算勝者，得算多也；未戰而廟算不勝者，得算少也；多算勝，少算不勝，而況於無算乎？吾以此觀之，勝負見矣。","sentenceIds":["art-of-war_ch-1_p-7_s-1","art-of-war_ch-1_p-7_s-2","art-of-war_ch-1_p-7_s-3","art-of-war_ch-1_p-7_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"夫未戰而廟算勝者，得算多也；未戰而廟算不勝者，得算少也；多算勝，少算不勝，而況於無算乎；吾以此觀之，勝負見矣。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《孫子兵法》〈始計〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「夫未戰而廟算」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"art-of-war_ch-2_p-1","chapterId":"art-of-war_ch-2","order":1,"canonicalText":"孫子曰：凡用兵之法，馳車千駟，革車千乘，帶甲十萬；千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。","sentenceIds":["art-of-war_ch-2_p-1_s-1","art-of-war_ch-2_p-1_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：大凡指揮軍事作戰的基本法則，配備輕型戰車一千輛，重型裝甲戰車一千輛，率領身穿鎧甲的步兵十萬人；千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈作戰〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「孫子曰：凡用兵之法，馳車千駟，革車千……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-2_p-2","chapterId":"art-of-war_ch-2","order":2,"canonicalText":"其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足。夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣！故兵聞拙速，未睹巧之久也；夫兵久而國利者，未之有也。","sentenceIds":["art-of-war_ch-2_p-2_s-1","art-of-war_ch-2_p-2_s-2","art-of-war_ch-2_p-2_s-3","art-of-war_ch-2_p-2_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足；夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣；故兵聞拙速，未睹巧之久也；夫兵久而國利者，從未有過這種情況。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈作戰〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「其用戰也，勝久則鈍兵挫銳，攻城則力屈……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-2_p-3","chapterId":"art-of-war_ch-2","order":3,"canonicalText":"故不盡知用兵之害者，則不能盡知用兵之利也。善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也。國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。","sentenceIds":["art-of-war_ch-2_p-3_s-1","art-of-war_ch-2_p-3_s-2","art-of-war_ch-2_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故不盡知用兵之害者，則不能盡知用兵之利也；善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也；國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈作戰〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「故不盡知用兵之害者，則不能盡知用兵之……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-2_p-4","chapterId":"art-of-war_ch-2","order":4,"canonicalText":"故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石。故殺敵者怒也，取敵之利者貨也。故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，卒善而養之，是謂勝敵而益強。","sentenceIds":["art-of-war_ch-2_p-4_s-1","art-of-war_ch-2_p-4_s-2","art-of-war_ch-2_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石；故殺敵者怒也，取敵之利者貨也；故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，去世善而養之，是謂勝敵而益強。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主旨】奪取敵方補給與裝備，可同時減少本國遠輸並增強自身；士氣與繳獲則靠激勵、整編和善待俘虜來轉化。\\n【詞義】「鍾」是容量單位；敵糧抵本國二十倍，重點在省去長途運輸成本；「𦮼稈」為豆秸、稈草一類飼料，字形各本有異；「怒」是激發同仇之氣；「貨」是以財物獎賞；「卒善而養之」多解為善待並收養俘卒。\\n【章法】前半談糧秣，後半談戰車與人員，從取敵資源推到「益強」。\\n【界限】善待俘虜在古文中帶有收編目的；現代規範要求人道待遇本身就是義務，不以能否為己所用為條件。"}},{"id":"art-of-war_ch-2_p-5","chapterId":"art-of-war_ch-2","order":5,"canonicalText":"故兵貴勝，不貴久；故知兵之將，民之司命，國家安危之主也。","sentenceIds":["art-of-war_ch-2_p-5_s-1","art-of-war_ch-2_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故用兵作戰最貴在迅速取勝，切忌拖延持久；故知兵之將，民之司命，國家安危之主也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《孫子兵法》〈作戰〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「故兵貴勝，不」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"art-of-war_ch-3_p-1","chapterId":"art-of-war_ch-3","order":1,"canonicalText":"孫子曰：凡用兵之法，全國為上，破國次之；全旅為上，破旅次之；全卒為上，破卒次之；全伍為上，破伍次之。是故百戰百勝，非善之善者也；不戰而屈人之兵，善之善者也。","sentenceIds":["art-of-war_ch-3_p-1_s-1","art-of-war_ch-3_p-1_s-2","art-of-war_ch-3_p-1_s-3","art-of-war_ch-3_p-1_s-4","art-of-war_ch-3_p-1_s-5","art-of-war_ch-3_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：大凡指揮軍事作戰的基本法則，全國為上，破國次之；全旅為上，破旅次之；全去世為上，破去世次之；全伍為上，破伍次之；是故百戰百勝，非善之善者也；不戰而屈人之兵，善之善者也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《孫子兵法·謀攻篇》，提出了「全勝」的戰略最高理想。\\n【詞義與名物】\\n全：保全，使之完整降服。破：擊破、毀滅。旅、卒、伍：古代軍隊的編制單位。屈人之兵：使敵軍屈服。\\n【兵家戰略】\\n「不戰而屈人之兵」是孫子兵法的核心思想之一。戰爭的目的是為了獲取利益，而非單純的破壞。透過謀略、威懾等非戰爭手段達成戰略目的，不僅能將自身損失降到最低，還能完整獲取敵方的資源，是兵法的最高境界。"}},{"id":"art-of-war_ch-3_p-2","chapterId":"art-of-war_ch-3","order":2,"canonicalText":"故上兵伐謀，其次伐交，其次伐兵，其下攻城。攻城之法，為不得已；修櫓轒轀，具器械，三月而後成；距闉，又三月而後已；將不勝其忿，而蟻附之，殺士卒三分之一，而城不拔者，此攻之災也。","sentenceIds":["art-of-war_ch-3_p-2_s-1","art-of-war_ch-3_p-2_s-2","art-of-war_ch-3_p-2_s-3","art-of-war_ch-3_p-2_s-4","art-of-war_ch-3_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故上兵伐謀，其次伐交，其次伐兵，其下攻城；攻城之法，為不得已；修櫓轒轀，具器械，三月而後成；距闉，又三月而後已；將不勝其忿，而蟻附之，殺士去世三分之一，而城不拔者，此攻之災也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段詳細論述了達成「全勝」的不同手段及其優劣層級，強烈反對強攻城池。\\n【詞義與名物】\\n伐謀：挫敗敵方的戰略企圖。伐交：破壞敵方的外交同盟。伐兵：在野外擊敗敵軍。櫓：大盾牌。轒轀（fén wēn）：四輪無底木車，外蒙牛皮，用於掩護士兵抵近城牆。距闉（yīn）：攻城時修築的土山。蟻附：像螞蟻一樣緣城牆而上。\\n【兵家戰略】\\n孫子將戰略手段分為謀、交、兵、城四個層次。伐謀與伐交成本最低、效益最高，攻城則耗時長、傷亡大、成功率低。這告誡將帥必須剋制情緒（不勝其忿），避免陷入消耗戰，凸顯了智將與莽將的區別。"}},{"id":"art-of-war_ch-3_p-3","chapterId":"art-of-war_ch-3","order":3,"canonicalText":"故善用兵者，屈人之兵，而非戰也；拔人之城，而非攻也；毀人之國，而非久也。必以全爭於天下，故兵不頓，利可全，此謀攻之法也。故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之。故小敵之堅，大敵之擒也。","sentenceIds":["art-of-war_ch-3_p-3_s-1","art-of-war_ch-3_p-3_s-2","art-of-war_ch-3_p-3_s-3","art-of-war_ch-3_p-3_s-4","art-of-war_ch-3_p-3_s-5","art-of-war_ch-3_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故善用兵者，屈人之兵，而非戰也；拔人之城，而非攻也；毀人之國，而非久也；必以全爭於天下，故兵不頓，利可全，此謀攻之法也；故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之；故小敵之堅，大敵之擒也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結了「謀攻」的核心法則，並提出了根據敵我兵力對比進行戰術選擇的具體原則。\\n【詞義與名物】\\n頓：疲勞、挫折。全爭：以保全自身的策略爭取勝利。倍：一倍，即兩倍於敵。分之：分散敵方兵力或分兵夾擊。小敵之堅：弱小的軍隊一味堅守。\\n【兵家戰略】\\n孫子強調軍事行動必須服務於整體利益（利可全）。在戰術層面，提出「十圍五攻」的絕對優勢作戰原則，並警告弱勢一方不可盲目硬拚，必須保持靈活，避免被優勢之敵殲滅，展現了高度的務實主義。"}},{"id":"art-of-war_ch-3_p-4","chapterId":"art-of-war_ch-3","order":4,"canonicalText":"夫將者，國之輔也，輔周則國必強，輔隙則國必弱。故軍之所以患於君者三：不知三軍之不可以進，而謂之進；不知三軍之不可以退，而謂之退；是謂縻軍。不知三軍之事，而同三軍之政，則軍士惑矣。不知三軍之權，而同三軍之任，則軍士疑矣。三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。","sentenceIds":["art-of-war_ch-3_p-4_s-1","art-of-war_ch-3_p-4_s-2","art-of-war_ch-3_p-4_s-3","art-of-war_ch-3_p-4_s-4","art-of-war_ch-3_p-4_s-5","art-of-war_ch-3_p-4_s-6","art-of-war_ch-3_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"夫將者，國之輔也，輔周則國必強，輔隙則國必弱；故軍用來……的緣由與途徑患於君者三：不知三軍之不可以進，而謂之進；不知三軍之不可以退，而謂之退；是謂縻軍；不知三軍之事，而同三軍之政，則軍士惑矣；不知三軍之權，而同三軍之任，則軍士疑矣；三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈謀攻〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「夫將者，國之輔也，輔周則國必強，輔隙……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-3_p-5","chapterId":"art-of-war_ch-3","order":5,"canonicalText":"故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；此五者，知勝之道也。","sentenceIds":["art-of-war_ch-3_p-5_s-1","art-of-war_ch-3_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；此五者，知勝之道也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結了判斷戰爭勝負的五個核心條件，即著名的「知勝有五」。\\n【詞義與名物】\\n眾寡之用：兵力多寡的運用方法。上下同欲：將帥與士兵目標一致、同心同德。虞：準備、戒備。御：控制、幹預。\\n【兵家戰略】\\n這五點涵蓋了戰機判斷、兵力運用、內部團結、戰備狀況與政軍關係。其中「上下同欲」強調內部凝聚力，「君不御」重申將帥的獨立指揮權。這五者構成了一個完整的取勝條件體系。"}},{"id":"art-of-war_ch-3_p-6","chapterId":"art-of-war_ch-3","order":6,"canonicalText":"故曰：知彼知己，百戰不殆；不知彼而知己，一勝一負；不知彼，不知己，每戰必敗。","sentenceIds":["art-of-war_ch-3_p-6_s-1","art-of-war_ch-3_p-6_s-2","art-of-war_ch-3_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"所以說：瞭解敵人，也瞭解自己，經歷百次戰鬥也不會有危險；不瞭解敵人，但瞭解自己，勝負的機率各佔一半；既不瞭解敵人，也不瞭解自己，那麼每次戰鬥必定都會失敗。","analysis":"【主題與背景】\\n這是《孫子兵法》中最廣為人知的一句話，總結了情報與資訊在戰爭中的決定性作用。\\n【詞義與名物】\\n知彼知己：瞭解敵方與我方的實際情況。殆：危險、失敗。\\n【兵家戰略】\\n情報是決策的基礎。孫子將「知彼」與「知己」並列，指出只有全面掌握雙方資訊，才能立於不敗之地。若資訊不全（不知彼而知己），勝算便大打折扣；若完全盲目，則必敗無疑。這是極為科學的資訊戰思維。"}},{"id":"art-of-war_ch-4_p-1","chapterId":"art-of-war_ch-4","order":1,"canonicalText":"孫子曰：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵。故善戰者，能為不可勝，不能使敵必可勝。故曰：勝可知，而不可為。","sentenceIds":["art-of-war_ch-4_p-1_s-1","art-of-war_ch-4_p-1_s-2","art-of-war_ch-4_p-1_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵；故善戰者，能為不可勝，不能使敵必可勝；故說：勝可知，而不可為。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《形篇》，探討攻守之道，強調先立於不敗之地，再尋求勝利。\\n【詞義與名物】\\n不可勝：不被擊敗的條件或態勢。可勝：可以擊敗敵人的機會。為：勉強去做、強求。\\n【兵家戰略】\\n孫子提出了極具哲理的防禦優先戰略。防禦（不可勝）取決於自身的準備與實力，是主觀可控的；進攻（可勝）則依賴敵人犯錯，是客觀不可控的。因此，最高明的將領總是穩紮穩打，不存僥倖心理，絕不冒險強求速勝。"}},{"id":"art-of-war_ch-4_p-2","chapterId":"art-of-war_ch-4","order":2,"canonicalText":"不可勝者，守也；可勝者，攻也。守則不足，攻則有餘。善守者，藏於九地之下；善攻者，動於九天之上，故能自保而全勝也。","sentenceIds":["art-of-war_ch-4_p-2_s-1","art-of-war_ch-4_p-2_s-2","art-of-war_ch-4_p-2_s-3","art-of-war_ch-4_p-2_s-4","art-of-war_ch-4_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"不可勝者，守也；可勝者，攻也；守則不足，攻則有餘；善守者，藏於九地之下；善攻者，動於九天之上，故能自保而全勝也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈軍形〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「不可勝者，守也；可勝者，攻也。守則不……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-4_p-3","chapterId":"art-of-war_ch-4","order":3,"canonicalText":"見勝，不過眾人之所知，非善之善者也。戰勝，而天下曰善，非善之善者也。故舉秋毫，不為多力；見日月，不為明目；聞雷霆，不為聰耳。古之善戰者，勝於易勝者；故善戰者之勝也，無智名，無勇功。故其戰勝不忒，不忒者，其措必勝，勝已敗者也。故善戰者，立於不敗之地，而不失敵之敗也。是故勝兵先勝，而後求戰；敗兵先戰，而後求勝。","sentenceIds":["art-of-war_ch-4_p-3_s-1","art-of-war_ch-4_p-3_s-2","art-of-war_ch-4_p-3_s-3","art-of-war_ch-4_p-3_s-4","art-of-war_ch-4_p-3_s-5","art-of-war_ch-4_p-3_s-6","art-of-war_ch-4_p-3_s-7","art-of-war_ch-4_p-3_s-8","art-of-war_ch-4_p-3_s-9","art-of-war_ch-4_p-3_s-10","art-of-war_ch-4_p-3_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"見勝，不過眾人之所知，非善之善者也；戰勝，而天下說：善，非善之善者也；故舉秋毫，不為多力；見日月，不為明目；聞雷霆，不為聰耳；古之善戰者，勝於易勝者；故善戰者之勝也，無智名，無勇功；故其戰勝不忒，不忒者，其措必勝，勝已敗者也；故善戰者，立於不敗之地，而不失敵之敗也；是故勝兵先勝，而後求戰；敗兵先戰，而後求勝。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈軍形〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「見勝，不過眾人之所知，非善之善者也。……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-4_p-4","chapterId":"art-of-war_ch-4","order":4,"canonicalText":"善用兵者，修道而保法，故能為勝敗之政。兵法：「一曰度，二曰量，三曰數，四曰稱，五曰勝；地生度，度生量，量生數，數生稱，稱生勝。」故勝兵若以鎰稱銖，敗兵若以銖稱鎰。勝者之戰民也，若決積水於千仞之谿，形也。","sentenceIds":["art-of-war_ch-4_p-4_s-1","art-of-war_ch-4_p-4_s-2","art-of-war_ch-4_p-4_s-3","art-of-war_ch-4_p-4_s-4","art-of-war_ch-4_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"善用兵者，修道而保法，故能為勝敗之政；兵法：一說：度，二說：量，三說：數，四說：稱，五說：勝；地生度，度生量，量生數，數生稱，稱生勝；故勝兵若以鎰稱銖，敗兵若以銖稱鎰；勝者之戰民也，若決積水於千仞之谿，形也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段從國家實力的角度，論述了實力（形）與勝負的因果關係。\\n【詞義與名物】\\n度、量、數、稱、勝：兵法五個遞進的計量概念。鎰、銖：古代重量單位，一鎰合二十兩，一兩合二十四銖。仞：古代長度單位，一仞約合八尺。谿：山谷。\\n【兵家戰略】\\n孫子指出軍事實力源自於國家的綜合國力（土地、物資、人口）。真正的勝利不是靠戰場上的僥倖，而是建立在絕對的實力優勢（以鎰稱銖）之上。這種壓倒性的實力一旦釋放，就像決開高山深谷的積水，勢不可擋。"}},{"id":"art-of-war_ch-5_p-1","chapterId":"art-of-war_ch-5","order":1,"canonicalText":"孫子曰：凡治眾如治寡，分數是也。鬥眾如鬥寡，形名是也。三軍之眾，可使必受敵而無敗者，奇正是也。兵之所加，如以碬投卵者，虛實是也。","sentenceIds":["art-of-war_ch-5_p-1_s-1","art-of-war_ch-5_p-1_s-2","art-of-war_ch-5_p-1_s-3","art-of-war_ch-5_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫子說：管理眾多軍隊就像管理少數軍隊一樣，這是軍隊編制與層級劃分的問題。指揮大軍作戰就像指揮小部隊作戰一樣，這是指揮通訊信號（如旌旗、金鼓）的問題。全軍部隊，能做到遭受敵人攻擊也不會失敗，這是靈活運用奇兵與正兵的問題。軍隊的攻擊，能像用石頭砸雞蛋一樣勢不可擋，這是運用虛實之道的結果。","analysis":"【主題與背景】\\n本段出自《勢篇》，論述了軍隊組織、指揮系統，以及戰術上的「奇正」與「虛實」。\\n【詞義與名物】\\n分數：軍隊的編制與組織結構。形名：指旌旗和金鼓，代表通訊與指揮系統。奇正：正規戰法與出其不意的奇襲。碬（xiá）：磨刀石，借指堅硬的石頭。虛實：兵力的薄弱與強大之處。\\n【兵家戰略】\\n強大的軍隊需要嚴密的組織（分數）與高效的指揮（形名）。在戰術層面，孫子提出了兩個極為重要的概念：透過「奇正」的變化確保不敗，透過避實擊虛（以碬投卵）實現摧枯拉朽的攻擊效果。"}},{"id":"art-of-war_ch-5_p-2","chapterId":"art-of-war_ch-5","order":2,"canonicalText":"凡戰者，以正合，以奇勝。故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；死而復生，四時是也。聲不過五，五聲之變，不可勝聽也。色不過五，五色之變，不可勝觀也。味不過五，五味之變，不可勝嘗也。戰勢不過奇正，奇正之變，不可勝窮也。奇正相生，如循環之無端，孰能窮之哉！","sentenceIds":["art-of-war_ch-5_p-2_s-1","art-of-war_ch-5_p-2_s-2","art-of-war_ch-5_p-2_s-3","art-of-war_ch-5_p-2_s-4","art-of-war_ch-5_p-2_s-5","art-of-war_ch-5_p-2_s-6","art-of-war_ch-5_p-2_s-7","art-of-war_ch-5_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"凡戰者，以正合，以奇勝；故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；死而復生，四時是也；聲不過五，五聲之變，不可勝聽也；色不過五，五色之變，不可勝觀也；味不過五，五味之變，不可勝嘗也；戰勢不過奇正，奇正之變，不可勝窮也；奇正相生，如循環之無端，孰能窮之哉。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈兵勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「凡戰者，以正合，以奇勝。故善出奇者，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-5_p-3","chapterId":"art-of-war_ch-5","order":3,"canonicalText":"激水之疾，至於漂石者，勢也。鷙鳥之擊，至於毀折者，節也。是故善戰者，其勢險，其節短，勢如張弩，節如機發。","sentenceIds":["art-of-war_ch-5_p-3_s-1","art-of-war_ch-5_p-3_s-2","art-of-war_ch-5_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"湍急的流水，速度快到能將石頭漂移，這就是它積聚的態勢（勢）。猛禽撲擊獵物，速度快到能將獵物的骨頭折斷，這就是它掌控的節奏與時機（節）。因此，善於作戰的人，他營造的態勢險峻威猛，他爆發的節奏短促有力。態勢就像拉滿的弓弩，節奏就像扣動弩機的瞬間。","analysis":"【主題與背景】\\n本段透過生動的比喻，具體說明「勢」與「節」在戰場上的威力。\\n【詞義與名物】\\n激水：湍急的水流。勢：積聚的能量與威勢。鷙鳥：猛禽。節：節奏、時機、爆發點。機：弩的發射機關。\\n【兵家戰略】\\n軍事打擊需要強大的動能（勢）與精準的時機（節）。「勢如張弩」強調戰前能量的極度蓄積與隱忍；「節如機發」強調攻擊時的迅猛、精準與短促，兩者結合才能產生巨大的破壞力。"}},{"id":"art-of-war_ch-5_p-4","chapterId":"art-of-war_ch-5","order":4,"canonicalText":"紛紛紜紜，鬥亂，而不可亂也。渾渾沌沌，形圓，而不可敗也。亂生於治，怯生於勇，弱生於強。治亂，數也。勇怯，勢也。強弱，形也。故善動敵者，形之，敵必從之；予之，敵必取之；以利動之，以實待之。","sentenceIds":["art-of-war_ch-5_p-4_s-1","art-of-war_ch-5_p-4_s-2","art-of-war_ch-5_p-4_s-3","art-of-war_ch-5_p-4_s-4","art-of-war_ch-5_p-4_s-5","art-of-war_ch-5_p-4_s-6","art-of-war_ch-5_p-4_s-7","art-of-war_ch-5_p-4_s-8","art-of-war_ch-5_p-4_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"紛紛紜紜，鬥亂，而不可亂也；渾渾沌沌，形圓，而不可敗也；亂生於治，怯生於勇，弱生於強；治亂，數也；勇怯，勢也；強弱，形也；故善動敵者，形之，敵必從之；予之，敵必取之；以利動之，以實待之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段論述偽裝與欺敵的策略，說明如何透過示弱來調動敵人。\\n【詞義與名物】\\n渾渾沌沌：模糊不清、變化莫測的樣子。形圓：陣形圓轉靈活。數：軍隊的編制和組織制度。形：表象、假象，動詞意為展示假象。\\n【兵家戰略】\\n這段話充滿了辯證法思想。為了調動敵人，將領必須善於偽裝，將治偽裝成亂，勇偽裝成怯，強偽裝成弱。但這些偽裝必須建立在高度的組織紀律（數）和強大的實力（形）之上。透過欺騙與利誘讓敵人陷入圈套，再以逸待勞予以殲滅。"}},{"id":"art-of-war_ch-5_p-5","chapterId":"art-of-war_ch-5","order":5,"canonicalText":"故善戰者，求之於勢，不責於人，故能擇人任勢；任勢者，其戰人也，如轉木石，木石之性，安則靜，危則動，方則止，圓則行。故善戰人之勢，如轉圓石於千仞之山者，勢也。","sentenceIds":["art-of-war_ch-5_p-5_s-1","art-of-war_ch-5_p-5_s-2","art-of-war_ch-5_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"因此，善於指揮作戰的人，總是從營造有利的態勢中去尋求勝利，而不去苛求部屬，所以能夠選拔合適的人才去順應和利用這種態勢。善於利用態勢的人，他指揮將士作戰，就像轉動木頭和石頭一樣。木頭和石頭的本性是：放在平坦安穩的地方就靜止，放在險峻陡峭的地方就會滾動，方形的容易停住，圓形的容易滾動。因此，善於指揮將士作戰所造就的態勢，就像將圓石從萬丈高山上推滾下來一樣，這就是所謂的「勢」。","analysis":"【主題與背景】\\n本段總結了「勢」的重要性，強調將帥應當專注於創造有利客觀條件，而非單純依賴士兵的個人英勇。\\n【詞義與名物】\\n責於人：苛求部屬、依賴個人的勇敢。任勢：利用有利的態勢。方則止，圓則行：方形物體容易靜止，圓形物體容易滾動。\\n【兵家戰略】\\n高明的將領不會把勝利的希望寄託在士兵的超常發揮上，而是致力於創造一種讓士兵不得不勇猛向前的客觀態勢（如居高臨下）。一旦這種勢頭形成（轉圓石於千仞之山），勝利就成了水到渠成、無法阻擋的自然規律。"}},{"id":"art-of-war_ch-6_p-1","chapterId":"art-of-war_ch-6","order":1,"canonicalText":"孫子曰：凡先處戰地而待敵者佚，後處戰地而趨戰者勞。故善戰者，致人而不致於人。能使敵人自至者，利之也；能使敵不得至者，害之也。故敵佚能勞之，飽能飢之，安能動之。","sentenceIds":["art-of-war_ch-6_p-1_s-1","art-of-war_ch-6_p-1_s-2","art-of-war_ch-6_p-1_s-3","art-of-war_ch-6_p-1_s-4","art-of-war_ch-6_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：凡先處戰地而待敵者佚，後處戰地而趨戰者勞；故善戰者，致人而不致於人；能使敵人自至者，利之也；能使敵不得至者，害之也；故敵佚能勞之，飽能飢之，安能動之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《虛實篇》，提出了掌握戰場主動權的核心原則：「致人而不致於人」。\\n【詞義與名物】\\n佚（yì）：安逸、從容。勞：疲勞。致人：調動敵人，掌握主動。致於人：被敵人調動，處於被動。害之：製造困難、危害來阻止敵人。\\n【兵家戰略】\\n掌握主動權是戰爭取勝的關鍵。孫子主張透過利誘與威脅，迫使敵人按照我方的意圖行動。無論敵人處於何種有利狀態（安逸、飽食、安穩），我方都應運用謀略打破其平衡，使其轉入劣勢，這充分體現了積極主動的戰略思維。"}},{"id":"art-of-war_ch-6_p-2","chapterId":"art-of-war_ch-6","order":2,"canonicalText":"出其所不趨，趨其所不意；行千里而不勞者，行於無人之地也；攻而必取者，攻其所不守也；守而必固者，守其所不攻也。故善攻者，敵不知其所守；善守者，敵不知其所攻。微乎微乎！至於無形；神乎神乎！至於無聲，故能為敵之司命。進而不可禦者，衝其虛也；退而不可追者，速而不可及也。故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。","sentenceIds":["art-of-war_ch-6_p-2_s-1","art-of-war_ch-6_p-2_s-2","art-of-war_ch-6_p-2_s-3","art-of-war_ch-6_p-2_s-4","art-of-war_ch-6_p-2_s-5","art-of-war_ch-6_p-2_s-6","art-of-war_ch-6_p-2_s-7","art-of-war_ch-6_p-2_s-8","art-of-war_ch-6_p-2_s-9","art-of-war_ch-6_p-2_s-10","art-of-war_ch-6_p-2_s-11","art-of-war_ch-6_p-2_s-12","art-of-war_ch-6_p-2_s-13","art-of-war_ch-6_p-2_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"出其所不趨，趨其所不意；行千里而不勞者，行於無人之地也；攻而必取者，攻其所不守也；守而必固者，守其所不攻也；故善攻者，敵不知其所守；善守者，敵不知其所攻；微乎微乎；至於無形；神乎神乎；至於無聲，故能為敵之司命；進而不可禦者，衝其虛也；退而不可追者，速而不可及也；故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈虛實〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「出其所不趨，趨其所不意；行千里而不勞……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-6_p-3","chapterId":"art-of-war_ch-6","order":3,"canonicalText":"故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也。則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。","sentenceIds":["art-of-war_ch-6_p-3_s-1","art-of-war_ch-6_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也；則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段論述如何透過情報與欺瞞手段，實現局部戰場上的絕對兵力優勢。\\n【詞義與名物】\\n形人：使敵人暴露陣形和部署。無形：隱蔽我方的陣形和意圖。專：集中。約：少、寡。\\n【兵家戰略】\\n孫子揭示了「以多勝少」的戰術祕訣：在總兵力可能劣勢的情況下，透過欺騙（無形）迫使敵人分兵防守（分），然後集中我方主力（專）在關鍵節點發動打擊。這是集中優勢兵力各個擊破的經典論述。"}},{"id":"art-of-war_ch-6_p-4","chapterId":"art-of-war_ch-6","order":4,"canonicalText":"吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣。故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡。寡者，備人者也；眾者，使人備己者也。","sentenceIds":["art-of-war_ch-6_p-4_s-1","art-of-war_ch-6_p-4_s-2","art-of-war_ch-6_p-4_s-3","art-of-war_ch-6_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣；故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡；寡者，備人者也；眾者，使人備己者也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段進一步解釋兵力分散與集中的辯證關係，強調保密與調動敵人的重要性。\\n【詞義與名物】\\n備：防備、駐守。寡：兵力單薄。使人備己：迫使敵人分散兵力來防備我方。\\n【兵家戰略】\\n防禦的困境在於「備多力分」。處處設防等於無防。高明的戰術是隱藏自己的主攻方向，讓敵人陷入無所適從的恐慌，被迫四處分兵把守。這樣，我方就能將敵人原本龐大的兵力稀釋，轉化為我方在局部戰場的絕對優勢。"}},{"id":"art-of-war_ch-6_p-5","chapterId":"art-of-war_ch-6","order":5,"canonicalText":"故知戰之地，知戰之日，則可千里而會戰。不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裏乎？以吾度之，越人之兵雖多，亦奚益於勝哉？故曰：勝可為也，敵雖眾，可使無鬥。","sentenceIds":["art-of-war_ch-6_p-5_s-1","art-of-war_ch-6_p-5_s-2","art-of-war_ch-6_p-5_s-3","art-of-war_ch-6_p-5_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故知戰之地，知戰之日，則可千里而會戰；不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裡乎；以吾度之，越人之兵雖多，亦奚益於勝哉；故說：勝可為也，敵雖眾，可使無鬥。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈虛實〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「故知戰之地，知戰之日，則可千里而會戰……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-6_p-6","chapterId":"art-of-war_ch-6","order":6,"canonicalText":"故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。故形兵之極，至於無形；無形，則深間不能窺，智者不能謀。因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；故其戰勝不復，而應形於無窮。","sentenceIds":["art-of-war_ch-6_p-6_s-1","art-of-war_ch-6_p-6_s-2","art-of-war_ch-6_p-6_s-3","art-of-war_ch-6_p-6_s-4","art-of-war_ch-6_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處；故形兵之極，至於無形；無形，則深間不能窺，智者不能謀；因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；故其戰勝不復，而應形於無窮。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結了偵察敵情的四種方法，並推崇「無形」與「應變」的最高指揮境界。\\n【詞義與名物】\\n策：籌算、分析。作：挑動、激怒。角：較量、小規模試探。形兵：部署陣形、展示軍力。深間：潛伏極深的間諜。應形：適應形勢變化。\\n【兵家戰略】\\n將領必須主動出擊（策、作、形、角）獲取敵情。同時，自身必須保持「無形」，讓敵人無從琢磨。真正的兵法不是死板的套路，而是根據每次不同的敵情、地形，隨機應變地創造出獨一無二的戰法（戰勝不復），這體現了高度的軍事創新精神。"}},{"id":"art-of-war_ch-6_p-7","chapterId":"art-of-war_ch-6","order":7,"canonicalText":"夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；水因地而制流，兵因敵而制勝。故兵無常勢，水無常形；能因敵變化而取勝，謂之神。故五行無常勝，四時無常位，日有短長，月有死生。","sentenceIds":["art-of-war_ch-6_p-7_s-1","art-of-war_ch-6_p-7_s-2","art-of-war_ch-6_p-7_s-3","art-of-war_ch-6_p-7_s-4","art-of-war_ch-6_p-7_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；水因地而制流，兵因敵而制勝；故兵無常勢，水無常形；能因敵變化而取勝，謂之神；故五行無常勝，四時無常位，日有短長，月有死生。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段以水為喻，提出了《孫子兵法》中極為重要的「兵無常勢」和「避實擊虛」的哲學思想。\\n【詞義與名物】\\n兵形：用兵的規律和態勢。實：堅強、防備嚴密之處。虛：薄弱、防備鬆懈之處。五行：金、木、水、火、土。死生：指月亮的盈虧圓缺。\\n【兵家戰略】\\n這是中國軍事哲學的巔峯之作。孫子用水的流動性來比喻戰爭的動態變化。水避高趨下，用兵則避實擊虛；水因地制流，用兵則因敵制勝。宇宙間萬物皆在變化（五行、四時、日月），軍事指揮也絕不能僵化，必須靈活應變，方能達到「神」的境界。"}},{"id":"art-of-war_ch-7_p-1","chapterId":"art-of-war_ch-7","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾，交和而舍，莫難於軍爭。軍爭之難者，以迂為直，以患為利。故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也。故軍爭為利，軍爭為危。","sentenceIds":["art-of-war_ch-7_p-1_s-1","art-of-war_ch-7_p-1_s-2","art-of-war_ch-7_p-1_s-3","art-of-war_ch-7_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：大凡指揮軍事作戰的基本法則，將受命於君，合軍聚眾，交和而舍，莫難於軍爭；軍爭之難者，以迂為直，以患為利；故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也；故軍爭為利，軍爭為危。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《軍爭篇》，探討軍隊如何透過機動行軍搶佔戰略要地與優勢。\\n【詞義與名物】\\n交和而舍：兩軍相交對峙，安營紮寨。軍爭：雙方爭奪有利的戰場和先機。以迂為直：表面上繞遠路，實則為最快達到目的的途徑。患：不利條件、危險。\\n【兵家戰略】\\n「軍爭」的核心在於爭奪主動權。孫子指出直線距離最短，但在戰略上有時卻是最慢或最危險的。「以迂為直」強調透過欺騙、隱蔽或繞過敵人防線，出其不意地到達目標。軍爭既有高收益（利），也伴隨高風險（危），考驗將領的智慧。"}},{"id":"art-of-war_ch-7_p-2","chapterId":"art-of-war_ch-7","order":2,"canonicalText":"舉軍而爭利，則不及；委軍而爭利，則輜重捐。是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；五十里而爭利，則蹶上將軍，其法半至；卅里而爭利，則三分之二至。是故軍無輜重則亡，無糧食則亡，無委積則亡。故不知諸侯之謀者，不能豫交；不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。","sentenceIds":["art-of-war_ch-7_p-2_s-1","art-of-war_ch-7_p-2_s-2","art-of-war_ch-7_p-2_s-3","art-of-war_ch-7_p-2_s-4","art-of-war_ch-7_p-2_s-5","art-of-war_ch-7_p-2_s-6","art-of-war_ch-7_p-2_s-7","art-of-war_ch-7_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"舉軍而爭利，則不及；委軍而爭利，則輜重捐；是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；五十里而爭利，則蹶上將軍，其法半至；卅里而爭利，則三分之二至；是故軍無輜重則亡，無糧食則亡，無委積則亡；故不知諸侯之謀者，不能豫交；不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段具體論述了長途奔襲的巨大風險，以及後勤保障和地理情報的重要性。\\n【詞義與名物】\\n委軍：丟下大部隊和輜重。輜重：軍用物資裝備。倍道兼行：以加倍的速度日夜行軍。蹶（jué）：受挫、損失。委積：糧秣物資的儲備。鄉導：當地的嚮導。\\n【兵家戰略】\\n急行軍雖然能出其不意，但會導致部隊疲勞、建制混亂（法十一而至）和後勤脫節。孫子極度重視後勤（輜重、糧食、委積），認為這是軍隊生存的根本。同時，也強調外交情報和地形嚮導是安全行軍的先決條件。"}},{"id":"art-of-war_ch-7_p-3","chapterId":"art-of-war_ch-7","order":3,"canonicalText":"故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆。掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。","sentenceIds":["art-of-war_ch-7_p-3_s-1","art-of-war_ch-7_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆；掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《孫子兵法》〈軍爭〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「故兵以詐立，」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"art-of-war_ch-7_p-4","chapterId":"art-of-war_ch-7","order":4,"canonicalText":"軍政曰：「言不相聞，故為金鼓；視不相見，故為旌旗。」夫金鼓旌旗者，所以一人之耳目也；人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也。故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。","sentenceIds":["art-of-war_ch-7_p-4_s-1","art-of-war_ch-7_p-4_s-2","art-of-war_ch-7_p-4_s-3","art-of-war_ch-7_p-4_s-4","art-of-war_ch-7_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"軍政說：言不相聞，故為金鼓；視不相見，故為旌旗；夫金鼓旌旗者，所以一人之耳目也；人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也；故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段論述軍隊指揮通訊系統的作用與運用方法。\\n【詞義與名物】\\n軍政：古代兵書名稱。金鼓：鑼鼓等打擊樂器，用於聽覺指揮。旌旗：旗幟，用於視覺指揮。一人之耳目：統一全軍將士的聽覺和視覺。\\n【兵家戰略】\\n大兵團作戰，個人英雄主義（勇者獨進）或逃跑主義（怯者獨退）都會破壞整體陣型。透過金鼓旌旗的統一指揮，軍隊被整合成一個不可分割的有機整體。同時，根據晝夜環境的不同靈活切換通訊手段，展現了實用主義的指揮藝術。"}},{"id":"art-of-war_ch-7_p-5","chapterId":"art-of-war_ch-7","order":5,"canonicalText":"故三軍可奪氣，將軍可奪心。是故朝氣銳，晝氣惰，暮氣歸；故善用兵者，避其銳氣，擊其惰歸，此治氣者也。以治待亂，以靜待譁，此治心者也。以近待遠，以佚待勞，以飽待飢，此治力者也。","sentenceIds":["art-of-war_ch-7_p-5_s-1","art-of-war_ch-7_p-5_s-2","art-of-war_ch-7_p-5_s-3","art-of-war_ch-7_p-5_s-4","art-of-war_ch-7_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"因此，對於敵方軍隊，可以挫傷其士氣；對於敵方將領，可以動搖其決心。一般來說，軍隊早晨剛出發時士氣銳盛，到了中午士氣就會懈怠，到了傍晚士氣就會衰落，士兵只一心想著回營休息。因此，善於用兵的人，會避開敵軍銳盛的士氣，而選擇在敵軍懈怠、思歸的時候發動攻擊，這就是掌握和控制「士氣」的方法。用我方的嚴整肅穆來對待敵軍的混亂，用我方的鎮定從容來對待敵軍的喧譁，這就是掌握和控制「心理」的方法。用我方靠近戰場來等待遠道而來的敵軍，用我方的休整安逸來等待疲憊的敵軍，用我方的糧食充足來等待飢餓的敵軍，這就是掌握和控制「戰鬥力」的方法。","analysis":"【主題與背景】\\n本段提出了心理戰與能量管理的「四治」原則：治氣、治心、治力。\\n【詞義與名物】\\n氣：士氣、鬥志。奪心：動搖將帥的理智與決心。朝、晝、暮：比喻戰爭的不同階段或軍隊作戰時間的推移。譁：喧嘩、恐慌。\\n【兵家戰略】\\n孫子非常注重人的精神狀態與體能狀態。作戰不僅是物理力量的碰撞，更是士氣和心理的較量。透過避其銳氣、擊其惰歸，以及以治待亂、以佚待勞，我方可以在敵方心理與生理最薄弱的時刻發動致命一擊，以最小代價取得勝利。"}},{"id":"art-of-war_ch-7_p-6","chapterId":"art-of-war_ch-7","order":6,"canonicalText":"無邀正正之旗，勿擊堂堂之陣，此治變者也；故用兵之法，高陵勿向，背邱勿逆，佯北勿從，銳卒勿攻，餌兵勿食，歸師勿遏，圍師必闕，窮寇勿迫，此用兵之法也。","sentenceIds":["art-of-war_ch-7_p-6_s-1","art-of-war_ch-7_p-6_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"不要去攔截旗幟整齊、軍容嚴整的敵軍，不要去攻擊陣容強大、實力雄厚的敵軍，這就是掌握和應對「變局」的方法。因此，用兵的原則是：敵軍佔據高地時，不要仰攻；敵軍背靠高地時，不要正面迎擊；敵軍假裝敗退時，不要追擊；敵軍精銳部隊，不要硬攻；敵軍作為誘餌的小部隊，不要去喫掉它；敵軍撤退回國時，不要死死攔截；包圍敵軍時，必須留一個缺口；對於陷入絕境的敵軍，不要逼迫太甚，這些都是用兵的基本法則。","analysis":"【主題與背景】\\n本段列舉了戰場上的八條具體戰術禁忌，被稱為「八戒」。\\n【詞義與名物】\\n邀：攔截。正正：旗幟整齊的樣子。堂堂：陣容強大嚴整的樣子。高陵：高地、山丘。餌兵：作為誘餌的部隊。歸師：撤退回國的軍隊。闕：缺口。窮寇：陷入絕境、無路可退的敵軍。\\n【兵家戰略】\\n這些法則的核心是避免在敵人佔據優勢（地形、士氣或陣型）時硬拚，同時避免將敵人逼入絕境引發其死戰的決心（圍師必闕、窮寇勿迫）。給敵人留一條生路，反而能瓦解其抵抗意志，這體現了兵法中極其高明的心理戰與彈性思維。"}},{"id":"art-of-war_ch-8_p-1","chapterId":"art-of-war_ch-8","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾；圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。故將通於九變之利者，知用兵矣。將不通於九變之利者，雖知地形，不能得地之利矣。治兵不知九變之術，雖知地利，不能得人之用矣。","sentenceIds":["art-of-war_ch-8_p-1_s-1","art-of-war_ch-8_p-1_s-2","art-of-war_ch-8_p-1_s-3","art-of-war_ch-8_p-1_s-4","art-of-war_ch-8_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：大凡指揮軍事作戰的基本法則，將受命於君，合軍聚眾；圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受；故將通於九變之利者，知用兵矣；將不通於九變之利者，雖知地形，不能得地之利矣；治兵不知九變之術，雖知地利，不能得人之用矣。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《九變篇》，論述了戰場上九種需要靈活變通的特殊情況，強調將領的獨立決斷權。\\n【詞義與名物】\\n圮（pǐ）地：地形險惡、難以通行的地方。衢（qú）地：四通八達的交通樞紐。絕地：缺乏水草等生存條件的地方。九變：九種特殊情況下的變通處理方法（包括前面的五地和後面的五不）。\\n【兵家戰略】\\n軍事指揮最忌教條主義。孫子列舉的「五地」和「五不」（途不由、軍不擊等）要求將領必須根據實際情況打破常規。特別是「君命有所不受」，再次重申了軍事專業主義，將領的最高職責是爭取勝利，而非盲目服從可能導致失敗的遠程指令。"}},{"id":"art-of-war_ch-8_p-2","chapterId":"art-of-war_ch-8","order":2,"canonicalText":"是故智者之慮，必雜於利害，雜於利而務可信也，雜於害而患可解也。是故屈諸侯者以害，役諸侯者以業，趨諸侯者以利。","sentenceIds":["art-of-war_ch-8_p-2_s-1","art-of-war_ch-8_p-2_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"因此，明智的將領在考慮問題時，必定會將有利和不利的因素綜合起來考量。在不利的條件下考慮到有利的因素，所爭取勝利的信心就能堅定；在有利的條件下考慮到不利的因素，潛在的禍患就可以化解。因此，要用不利的手段去削弱敵對諸侯，用繁重的事務去勞役他們，用微小的利益去引誘他們四處奔波。","analysis":"【主題與背景】\\n本段提出了辯證的利害觀，並將其應用於對待敵國的外交與戰略手段上。\\n【詞義與名物】\\n雜：混合、綜合考量。信：伸張、堅定（通「伸」）。患可解：禍患可以消除。屈：使之屈服、削弱。役：勞役、消耗。趨：使之奔走疲於奔命。\\n【兵家戰略】\\n這是極具智慧的戰略思維：利與害是相伴相生的。高明的決策者永遠不會只看一面（順境防患，逆境圖存）。在對付敵國時，孫子不主張直接動武，而是透過製造麻煩（害）、增加負擔（業）、利誘調動（利），從內部和戰略上消耗、拖垮敵人。"}},{"id":"art-of-war_ch-8_p-3","chapterId":"art-of-war_ch-8","order":3,"canonicalText":"故用兵之法，無恃其不來，恃吾有以待之；無恃其不攻，恃吾有所不可攻也。","sentenceIds":["art-of-war_ch-8_p-3_s-1","art-of-war_ch-8_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故用兵之法，無恃其不來，恃吾有以待之；無恃其不攻，恃吾有所不可攻也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段是《孫子兵法》中關於戰備最著名的格言，強調將國家安全建立在自身實力的基礎上。\\n【詞義與名物】\\n恃：依賴、寄望於。待：等待、防備。不可攻：堅不可摧、無法被攻克。\\n【兵家戰略】\\n這是底線思維的完美體現。將軍事安全寄託在敵人的仁慈或疏忽上，是極度危險的。真正的安全感只能來源於自身的嚴陣以待和強大實力。這種「丟掉幻想，準備戰鬥」的思想，是防禦戰略的最高準則。"}},{"id":"art-of-war_ch-8_p-4","chapterId":"art-of-war_ch-8","order":4,"canonicalText":"故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；凡此五危，將之過也，用兵之災也。覆軍殺將，必以五危，不可不察也。","sentenceIds":["art-of-war_ch-8_p-4_s-1","art-of-war_ch-8_p-4_s-2","art-of-war_ch-8_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；凡此五危，將之過也，用兵之災也；覆軍殺將，必以五危，不可不察也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《孫子兵法》〈九變〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「故將有五危：」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"art-of-war_ch-9_p-1","chapterId":"art-of-war_ch-9","order":1,"canonicalText":"孫子曰：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也。絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利。欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也。絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也。平陸處易，右背高，前死後生，此處平陸之軍也。凡此四軍之利，黃帝之所以勝四帝也。","sentenceIds":["art-of-war_ch-9_p-1_s-1","art-of-war_ch-9_p-1_s-2","art-of-war_ch-9_p-1_s-3","art-of-war_ch-9_p-1_s-4","art-of-war_ch-9_p-1_s-5","art-of-war_ch-9_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也；絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利；欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也；絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也；平陸處易，右背高，前死後生，此處平陸之軍也；凡此四軍之利，黃帝用來……的緣由與途徑勝四帝也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《行軍篇》，詳細論述了軍隊在山地、江河、沼澤、平原四種主要地形上的行軍、駐紮與作戰原則。\\n【詞義與名物】\\n處軍：軍隊的部署和駐紮。相敵：觀察敵情。絕：橫越。視生：視野開闊、有水草生機之地。客：指前來進攻的敵軍。半濟：渡河渡到一半。斥澤：鹽鹼沼澤地。前死後生：前方地勢平緩開闊，後方有高地可作退路。\\n【兵家戰略】\\n本段強調了「因地制宜」。山地要佔據制高點；水戰要利用「半渡而擊」的脆弱期；沼澤地要盡快脫離以防機動力喪失；平原要保證後路安全。這些實戰經驗展示了古代軍隊如何最大化利用地形優勢，避免陷入自然環境的陷阱。"}},{"id":"art-of-war_ch-9_p-2","chapterId":"art-of-war_ch-9","order":2,"canonicalText":"凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝。邱陵隄防，必處其陽，而右背之，此兵之利，地之助也。上雨水沫至，欲涉者，待其定也。凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；吾遠之，敵近之；吾迎之，敵背之。軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。","sentenceIds":["art-of-war_ch-9_p-2_s-1","art-of-war_ch-9_p-2_s-2","art-of-war_ch-9_p-2_s-3","art-of-war_ch-9_p-2_s-4","art-of-war_ch-9_p-2_s-5","art-of-war_ch-9_p-2_s-6","art-of-war_ch-9_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝；邱陵隄防，必處其陽，而右背之，此兵之利，地之助也；上雨水沫至，欲涉者，待其定也；凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；吾遠之，敵近之；吾迎之，敵背之；軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結了軍隊駐紮的衛生防護原則，並列舉了必須避開的六種危險地形，以及防範伏擊的注意事項。\\n【詞義與名物】\\n貴陽而賤陰：喜歡向陽乾燥，避開陰暗潮濕。養生處實：駐紮在水草豐美、物資充實的地方。百疾：各種傳染病。絕澗、天井、天牢、天羅、天陷、天隙：古代兵法中極其兇險的六種自然地形。潢井：低窪積水之處。蒹葭（jiān jiā）：蘆葦。翳薈（yì huì）：草木茂盛遮蔽的地方。伏姦：埋伏軍隊或隱藏奸細。\\n【兵家戰略】\\n孫子展現了卓越的軍事後勤與安全意識。軍隊的健康（無百疾）是保持戰鬥力的前提。面對極端危險地形（六天），最聰明的做法是徹底避開，並設法將敵人逼入其中。同時，對複雜地貌保持高度警惕，防止被伏擊，體現了縝密的偵察思維。"}},{"id":"art-of-war_ch-9_p-3","chapterId":"art-of-war_ch-9","order":3,"canonicalText":"敵近而靜者，恃其險也。遠而挑戰者，欲人之進也。其所居易者，利也。眾樹動者，來也。眾草多障者，疑也。鳥起者，伏也。獸駭者，覆也。塵：高而銳者，車來也；卑而廣者，徒來也；散而條違者，樵採也；少而往來者，營軍也。辭卑而益備者，進也。辭強而進驅者，退也。輕車先出其側者，陣也。無約而請和者，謀也。奔走而陳兵者，期也。半進半退者，誘也。仗而立者，飢也。汲而先飲者，渴也。見利而不進者，勞也。鳥集者，虛也。夜呼者，恐也。軍擾者，將不重也。旌旗動者，亂也。吏怒者，倦也。殺馬肉食者，軍無糧也。懸缶不返其舍者，窮寇也。諄諄翕翕，徐與人言者，失眾也。數賞者，窘也。數罰者，困也。先暴而後畏其眾者，不精之至也。來委謝者，欲休息也。兵怒而相迎，久而不合，又不相去，必謹察之。","sentenceIds":["art-of-war_ch-9_p-3_s-1","art-of-war_ch-9_p-3_s-2","art-of-war_ch-9_p-3_s-3","art-of-war_ch-9_p-3_s-4","art-of-war_ch-9_p-3_s-5","art-of-war_ch-9_p-3_s-6","art-of-war_ch-9_p-3_s-7","art-of-war_ch-9_p-3_s-8","art-of-war_ch-9_p-3_s-9","art-of-war_ch-9_p-3_s-10","art-of-war_ch-9_p-3_s-11","art-of-war_ch-9_p-3_s-12","art-of-war_ch-9_p-3_s-13","art-of-war_ch-9_p-3_s-14","art-of-war_ch-9_p-3_s-15","art-of-war_ch-9_p-3_s-16","art-of-war_ch-9_p-3_s-17","art-of-war_ch-9_p-3_s-18","art-of-war_ch-9_p-3_s-19","art-of-war_ch-9_p-3_s-20","art-of-war_ch-9_p-3_s-21","art-of-war_ch-9_p-3_s-22","art-of-war_ch-9_p-3_s-23","art-of-war_ch-9_p-3_s-24","art-of-war_ch-9_p-3_s-25","art-of-war_ch-9_p-3_s-26","art-of-war_ch-9_p-3_s-27","art-of-war_ch-9_p-3_s-28","art-of-war_ch-9_p-3_s-29","art-of-war_ch-9_p-3_s-30","art-of-war_ch-9_p-3_s-31","art-of-war_ch-9_p-3_s-32","art-of-war_ch-9_p-3_s-33"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"敵近而靜者，恃其險也；遠而挑戰者，欲人之進也；其所居易者，利也；眾樹動者，來也；眾草多障者，疑也；鳥起者，伏也；獸駭者，覆也；塵：高而銳者，車來也；卑而廣者，徒來也；散而條違者，樵採也；少而往來者，營軍也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段列舉了三十二種偵察敵情的具體現象，是古代軍事情報分析的經典指南。\\n【詞義與名物】\\n條違：散亂成條狀。辭卑：使者言辭謙卑。期：預定交戰的時刻。懸缶：掛起打水的瓦罐，指不準備生火做飯。諄諄翕翕：說話低聲下氣、小心翼翼的樣子。\\n【兵家戰略】\\n這是「見微知著」的戰場洞察力訓練。孫子教導將領透過自然現象（鳥飛獸駭、塵土形狀）、敵人行為（言語、動作）和軍營狀態，反推敵人的真實意圖和內部危機（飢渴、疲勞、恐慌）。這種透過表象看本質的情報分析方法，至今仍有極高的軍事價值。"}},{"id":"art-of-war_ch-9_p-4","chapterId":"art-of-war_ch-9","order":4,"canonicalText":"兵非貴益多，惟無武進，足以併力料敵取人而已。夫惟無慮而易敵者，必擒於人。","sentenceIds":["art-of-war_ch-9_p-4_s-1","art-of-war_ch-9_p-4_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"兵非貴益多，惟無武進，足以併力料敵取人而已；夫惟無慮而易敵者，必擒於人。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結兵力多寡與戰勝的關係，反對盲目追求兵力數量。\\n【詞義與名物】\\n益多：越多越好。武進：逞勇冒進。併力：集中兵力。料敵：準確判斷敵情。易敵：輕視敵人。\\n【兵家戰略】\\n孫子認為兵力多寡不是決定勝負的唯一標準。如果在戰略和情報上出錯（無慮、易敵），數量優勢反而會成為負擔。勝利的關鍵在於不犯錯（無武進）、集中優勢兵力（併力），以及準確的情報分析（料敵）。這再次強調了智謀高於單純的武力。"}},{"id":"art-of-war_ch-9_p-5","chapterId":"art-of-war_ch-9","order":5,"canonicalText":"卒未親附而罰之，則不服，不服則難用。卒已親附而罰不行，則不可用。故令之以文，齊之以武，是謂必取。令素行以教其民，則民服；令不素行以教其民，則民不服；令素行，與眾相得也。","sentenceIds":["art-of-war_ch-9_p-5_s-1","art-of-war_ch-9_p-5_s-2","art-of-war_ch-9_p-5_s-3","art-of-war_ch-9_p-5_s-4","art-of-war_ch-9_p-5_s-5","art-of-war_ch-9_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"士兵還沒有親近依附將領時，就對他們進行處罰，他們就不會心服，不服從就很難指揮他們作戰。士兵已經親近依附將領了，如果軍紀法規不能貫徹執行，這樣的軍隊同樣不能用來作戰。因此，要用思想政治教育（文）來引導他們，用嚴格的軍法紀律（武）來統整他們，這樣就必定能取得他們的擁護。如果平時能貫徹執行命令來教育士兵，士兵就會服從；如果平時不能貫徹執行命令，士兵就不會服從。平時命令能得到嚴格執行的，說明將帥與士兵之間建立了深厚的互信。","analysis":"【主題與背景】\\n本段探討治軍之道，提出了恩威並施（令之以文，齊之以武）的帶兵原則。\\n【詞義與名物】\\n親附：親近、依附、產生信任感。文：政治教化、關懷愛護。武：軍紀、軍法。素行：平時一貫執行。相得：互相融洽、互相信任。\\n【兵家戰略】\\n這是一套極為成熟的領導力理論。將領不能一味依賴嚴刑峻法，必須先建立情感認同（親附），否則懲罰只會引發反彈。但有了感情後，又不能廢弛軍紀，必須「文武並用」。同時，孫子強調紀律的養成在於平時的貫徹（素行），而非戰時的臨時抱佛腳。"}},{"id":"art-of-war_ch-10_p-1","chapterId":"art-of-war_ch-10","order":1,"canonicalText":"孫子曰：地形有通者，有掛者，有支者，有隘者，有險者，有遠者。我可以往，彼可以來，曰通；通形者，先居高陽，利糧道以戰，則利。可以往，難以返，曰掛；掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利。我出而不利，彼出而不利，曰支；支形者，敵雖利我，我無出也；引而去之，令敵半出而擊之，利。隘形者，我先居之，必盈以待敵；若敵先居之，盈而勿從，不盈而從之。險形者，我先居之，必居高陽以待敵；若敵先居之，引而去之，勿從也。遠形者，勢均，難以挑戰，戰而不利。凡此六者，地之道也，將之至任，不可不察也。","sentenceIds":["art-of-war_ch-10_p-1_s-1","art-of-war_ch-10_p-1_s-2","art-of-war_ch-10_p-1_s-3","art-of-war_ch-10_p-1_s-4","art-of-war_ch-10_p-1_s-5","art-of-war_ch-10_p-1_s-6","art-of-war_ch-10_p-1_s-7","art-of-war_ch-10_p-1_s-8","art-of-war_ch-10_p-1_s-9","art-of-war_ch-10_p-1_s-10","art-of-war_ch-10_p-1_s-11","art-of-war_ch-10_p-1_s-12","art-of-war_ch-10_p-1_s-13","art-of-war_ch-10_p-1_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：地形有通者，有掛者，有支者，有隘者，有險者，有遠者；我可以往，彼可以來，說：通；通形者，先居高陽，利糧道以戰，則利；可以往，難以返，說：掛；掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利；我出而不利，彼出而不利，說：支；支形者，敵雖利我，我無出也；引而去之，令敵半出而擊之，利；隘形者，我先居之，必盈以待敵；若敵先居之，盈而勿從，不盈而從之；險形者，我先居之，必居高陽以待敵；若敵先居之，引而去之，勿從也；遠形者，勢均，難以挑戰，戰而不利；凡此六者，地之道也，將之至任，不可不察也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《地形篇》，系統分類了六種典型戰場地形，並提出了相應的戰術原則。\\n【詞義與名物】\\n通：交通便利的地形。掛：容易陷入、難以撤退的地形。支：雙方都不易展開、相持不下的地形。隘：狹窄的地形。險：險峻的地形。遠：距離遙遠、難以接戰的地形。盈：充滿，指部署重兵。\\n【兵家戰略】\\n地形是戰場的客觀基礎。孫子的核心思想是搶佔先機（先居）與趨利避害。在「通」地要保證後勤；在「隘」和「險」地要堅決搶佔制高點和咽喉要道；在「掛」和「支」地則考驗將領的忍耐與誘敵技巧。這些原則將地理環境完美融入了戰術體系之中。"}},{"id":"art-of-war_ch-10_p-2","chapterId":"art-of-war_ch-10","order":2,"canonicalText":"故兵有走者，有弛者，有陷者，有崩者，有亂者，有北者；凡此六者，非天地之災，將之過也。夫勢均，以一擊十，曰走。卒強吏弱，曰弛。吏強卒弱，曰陷。大吏怒而不服，遇敵懟而自戰，將不知其能，曰崩。將弱不嚴，教道不明，吏卒無常，陳兵縱橫，曰亂。將不能料敵，以少合眾，以弱擊強，兵無選鋒，曰北。凡此六者，敗之道也。將之至任，不可不察也。","sentenceIds":["art-of-war_ch-10_p-2_s-1","art-of-war_ch-10_p-2_s-2","art-of-war_ch-10_p-2_s-3","art-of-war_ch-10_p-2_s-4","art-of-war_ch-10_p-2_s-5","art-of-war_ch-10_p-2_s-6","art-of-war_ch-10_p-2_s-7","art-of-war_ch-10_p-2_s-8","art-of-war_ch-10_p-2_s-9","art-of-war_ch-10_p-2_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故兵有走者，有弛者，有陷者，有駕崩逝世者，有亂者，有北者；凡此六者，非天地之災，將之過也；夫勢均，以一擊十，說：走；去世強吏弱，說：弛；吏強去世弱，說：陷；大吏怒而不服，遇敵懟而自戰，將不知其能，說：駕崩逝世；將弱不嚴，教道不明，吏去世無常，陳兵縱橫，說：亂；將不能料敵，以少合眾，以弱擊強，兵無選鋒，說：北；凡此六者，敗之道也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結了六種由於將領指揮與管理失誤導致的軍隊敗局，稱為「六敗」。\\n【詞義與名物】\\n走：敗逃。弛：鬆弛、失控。陷：陷入困境、崩塌。崩：崩潰。北：敗北。選鋒：精銳的突擊部隊。懟（duì）：怨恨。\\n【兵家戰略】\\n這是一份深刻的軍隊內部危機診斷書。孫子將戰敗的原因歸咎於將帥的主觀錯誤（將之過），而非客觀條件。這些錯誤涵蓋了兵力調配不當（走、北）、將士能力不匹配（弛、陷）、內部將帥不和（崩）以及日常軍紀廢弛（亂）。這強調整個軍隊的管理系統和將帥的統御能力是決定勝負的內在關鍵。"}},{"id":"art-of-war_ch-10_p-3","chapterId":"art-of-war_ch-10","order":3,"canonicalText":"夫地形者，兵之助也。料敵制勝，計險阨遠近，上將之道也。知此而用戰者，必勝；不知此而用戰者必敗。故戰道必勝；主曰：無戰；必戰可也。戰道不勝，主曰必戰，無戰可也。故進不求名，退不避罪，唯民是保，而利於主，國之寶也。","sentenceIds":["art-of-war_ch-10_p-3_s-1","art-of-war_ch-10_p-3_s-2","art-of-war_ch-10_p-3_s-3","art-of-war_ch-10_p-3_s-4","art-of-war_ch-10_p-3_s-5","art-of-war_ch-10_p-3_s-6","art-of-war_ch-10_p-3_s-7","art-of-war_ch-10_p-3_s-8","art-of-war_ch-10_p-3_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"夫地形者，兵之助也；料敵制勝，計險阨遠近，上將之道也；知此而用戰者，必勝；不知此而用戰者必敗；故戰道必勝；主說：無戰；必戰可也；戰道不勝，主說：必戰，無戰可也；故進不求名，退不避罪，唯民是保，而利於主，國之寶也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段探討將領的專業素養與政治擔當，再次強調「將在外，君命有所不受」的獨立指揮原則。\\n【詞義與名物】\\n兵之助：用兵作戰的輔助條件。阨（è）：狹窄險要的地形。進不求名，退不避罪：前進作戰不是為了個人名譽，撤退防守不怕承擔罪責。\\n【兵家戰略】\\n孫子描繪了理想將領（上將）的兩大特質：一是精通戰術與地理的極高軍事素養；二是超越個人私利、具備極高政治道德（保民利主）的責任感。為了國家利益，將領必須敢於違抗君主錯誤的幹預指令。這種將「國家利益」置於「君主命令」之上的觀點，在古代具有極高的進步意義。"}},{"id":"art-of-war_ch-10_p-4","chapterId":"art-of-war_ch-10","order":4,"canonicalText":"視卒如嬰兒，故可與之赴深谿；視卒如愛子，故可與之俱死。厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。","sentenceIds":["art-of-war_ch-10_p-4_s-1","art-of-war_ch-10_p-4_s-2","art-of-war_ch-10_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"對待士兵就像對待嬰兒一樣關懷備至，士兵就會跟隨將領赴湯蹈火；對待士兵就像對待自己鍾愛的孩子一樣，士兵就會與將領生死與共。但是，如果對士兵過分厚待卻不能驅使他們作戰，過分溺愛卻不能讓他們服從命令，軍隊內部混亂卻不能加以整治，這就如同寵壞的嬌慣孩子一樣，是完全不能用來打仗的。","analysis":"【主題與背景】\\n本段論述將領與士兵的關係，強調恩威並施、慈愛與嚴格必須結合的帶兵之道。\\n【詞義與名物】\\n深谿：深谷，比喻危險的地方。厚、愛：優厚、疼愛。驕子：被寵壞的孩子。\\n【兵家戰略】\\n孫子深刻認識到，軍隊的凝聚力來自於將帥對士兵真誠的愛護。但同時他也警告，純粹的溺愛會導致軍隊失去紀律和戰鬥力。只有將深厚的感情（視如愛子）與嚴格的軍法紀律（能使、能令、能治）相結合，才能打造出戰無不勝的鐵軍。"}},{"id":"art-of-war_ch-10_p-5","chapterId":"art-of-war_ch-10","order":5,"canonicalText":"知吾卒之可以擊，而不知敵之不可擊，勝之半也；知敵之可擊，而不知吾卒之不可擊，勝之半也。知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。故知兵者，動而不迷，舉而不窮。故曰：知彼知己，勝乃不殆；知天知地，勝乃可全。","sentenceIds":["art-of-war_ch-10_p-5_s-1","art-of-war_ch-10_p-5_s-2","art-of-war_ch-10_p-5_s-3","art-of-war_ch-10_p-5_s-4","art-of-war_ch-10_p-5_s-5","art-of-war_ch-10_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"只瞭解我方軍隊具備攻擊的實力，卻不瞭解敵軍的防禦無懈可擊，勝利的把握只有一半。只瞭解敵軍存在可以被攻擊的弱點，卻不瞭解我方軍隊實力不足以發動攻擊，勝利的把握也只有一半。瞭解敵軍可以被攻擊，也瞭解我方軍隊具備攻擊的實力，卻不瞭解戰場的地形不適合展開戰鬥，勝利的把握仍然只有一半。因此，真正懂得用兵的人，一旦採取行動就不會迷失方向，一旦發起攻擊就辦法無窮。所以說：瞭解敵人，也瞭解自己，取得勝利就不會有危險；既瞭解天時，又瞭解地利，勝利就可以完全確保了。","analysis":"【主題與背景】\\n本段總結《地形篇》，將「知彼知己」的理論進一步擴展，加入了「知天知地」的客觀維度。\\n【詞義與名物】\\n勝之半：勝算只有一半。動而不迷：行動明確，不迷失方向。舉而不窮：措施應變無窮盡。殆：危險。全：完美、完全。\\n【兵家戰略】\\n孫子將戰略評估的維度推向了極致。僅僅瞭解敵我雙方的兵力（知彼知己）是不夠的，戰場是一個包含自然環境（天、地）的複雜系統。只有將天時、地利、敵情、我方實力這四個要素完美整合，才能做到決策無誤（動而不迷），從而達到「勝乃可全」的最高境界。"}},{"id":"art-of-war_ch-11_p-1","chapterId":"art-of-war_ch-11","order":1,"canonicalText":"孫子曰：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地。諸侯自戰其地者，為散地。入人之地而不深者，為輕地。我得則利，彼得亦利者，為爭地。我可以往，彼可以來者，為交地。諸侯之地三屬，先至而得天下之眾者，為衢地。入人之地深，背城邑多者，為重地。山林、險阻、沮澤，凡難行之道者，為圮地。所由入者隘，所從歸者迂，彼寡可以擊吾之眾者，為圍地。疾戰則存，不疾戰則亡者，為死地。是故散地則無戰，輕地則無止，爭地則無攻，交地則無絕，衢地則合交，重地則掠，圮地則行，圍地則謀，死地則戰。","sentenceIds":["art-of-war_ch-11_p-1_s-1","art-of-war_ch-11_p-1_s-2","art-of-war_ch-11_p-1_s-3","art-of-war_ch-11_p-1_s-4","art-of-war_ch-11_p-1_s-5","art-of-war_ch-11_p-1_s-6","art-of-war_ch-11_p-1_s-7","art-of-war_ch-11_p-1_s-8","art-of-war_ch-11_p-1_s-9","art-of-war_ch-11_p-1_s-10","art-of-war_ch-11_p-1_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地；諸侯自戰其地者，為散地；入人之地而不深者，為輕地；我得則利，彼得亦利者，為爭地；我可以往，彼可以來者，為交地；諸侯之地三屬，先至而得天下之眾者，為衢地；入人之地深，背城邑多者，為重地；山林、險阻、沮澤，凡難行之道者，為圮地。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈九地〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「孫子曰：用兵之法，有散地，有輕地，有……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-11_p-2","chapterId":"art-of-war_ch-11","order":2,"canonicalText":"古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，卒離而不集，兵合而不齊。合於利而動，不合於利而止。敢問：「敵眾整而將來，待之若何？」曰：「先奪其所愛，則聽矣；兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。」","sentenceIds":["art-of-war_ch-11_p-2_s-1","art-of-war_ch-11_p-2_s-2","art-of-war_ch-11_p-2_s-3","art-of-war_ch-11_p-2_s-4","art-of-war_ch-11_p-2_s-5","art-of-war_ch-11_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，去世離而不集，兵合而不齊；合於利而動，不合於利而止；敢問：敵眾整而將來，待之若何；說：先奪其所愛，則聽矣；兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段探討如何瓦解敵軍的組織體系，以及面對強大敵軍時的突襲策略。\\n【詞義與名物】\\n不相及：無法互相聯絡、救援。奪其所愛：奪取敵人最重視的要害或戰略資源。兵之情主速：用兵作戰最重要在於神速。不虞：意想不到。\\n【兵家戰略】\\n瓦解敵軍體系（使其前後不相及、上下不相收）是擊敗大軍的關鍵。當面對強敵時，孫子提出了經典的「不對稱作戰」原則：不與敵人正面硬碰，而是發揮極致的速度（主速），攻擊其必救的軟肋（先奪其所愛），打亂其部署，從而將主動權搶奪過來。"}},{"id":"art-of-war_ch-11_p-3","chapterId":"art-of-war_ch-11","order":3,"canonicalText":"凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力。兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥。是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之。吾士無餘財，非惡貨也；無餘命，非惡壽也。令發之日，士卒坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。","sentenceIds":["art-of-war_ch-11_p-3_s-1","art-of-war_ch-11_p-3_s-2","art-of-war_ch-11_p-3_s-3","art-of-war_ch-11_p-3_s-4","art-of-war_ch-11_p-3_s-5","art-of-war_ch-11_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力；兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥；是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之；吾士無餘財，非惡貨也；無餘命，非惡壽也；令發之日，士去世坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段深刻分析了深入敵國作戰時，地理環境對士兵心理的巨大影響，以及如何利用「死地」激發軍隊潛能。\\n【詞義與名物】\\n客：指進入敵國作戰的軍隊。專：軍心專一、意志集中。禁祥去疑：禁止迷信占卜，消除軍心的疑慮動搖。諸劌之勇：專諸（刺客）和曹劌（勇士）那樣視死如歸的勇氣。涕交頤：眼淚流滿臉頰（反映面臨死亡的真實恐懼）。\\n【兵家戰略】\\n這是心理學在軍事上的巔峯應用。孫子明白人性畏死求生，但在無路可退的「死地」，這種恐懼可以轉化為絕地反擊的巨大爆發力。將領不需空洞的說教，只需透過環境的極限壓迫，就能自然激發出士兵最原始的求生本能與死戰決心。"}},{"id":"art-of-war_ch-11_p-4","chapterId":"art-of-war_ch-11","order":4,"canonicalText":"故善用兵者，譬如率然；率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至。敢問：「兵可使如率然乎？」曰：「可。」夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手。是故，方馬埋輪，未足恃也，齊勇若一，政之道也；剛柔皆得，地之理也。故善用兵者，攜手若使一人，不得已也。","sentenceIds":["art-of-war_ch-11_p-4_s-1","art-of-war_ch-11_p-4_s-2","art-of-war_ch-11_p-4_s-3","art-of-war_ch-11_p-4_s-4","art-of-war_ch-11_p-4_s-5","art-of-war_ch-11_p-4_s-6","art-of-war_ch-11_p-4_s-7","art-of-war_ch-11_p-4_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故善用兵者，譬如率然；率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至；敢問：兵可使如率然乎；說：可；夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手；是故，方馬埋輪，未足恃也，齊勇若一，政之道也；剛柔皆得，地之理也；故善用兵者，攜手若使一人，不得已也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段透過「率然」與「同舟共濟」兩個比喻，論述軍隊的高度協同性與生死與共的凝聚力。\\n【詞義與名物】\\n率然：傳說中常山的一種蛇，比喻陣型嚴密、首尾呼應。方馬埋輪：把馬匹拴在一起，把戰車輪子埋在土裡，表示死守不退。政之道：組織管理和教育引導的方法。\\n【兵家戰略】\\n軍隊的協同作戰不能僅靠機械的陣地防禦（方馬埋輪）。孫子指出，真正的戰鬥力來自於內在的利益與命運綁定。即使是世仇（吳越同舟），在共同的生死危機面前也會爆發出驚人的團結。將領的任務就是創造這種休慼與共的環境，使全軍成為一個高度敏捷的有機體。"}},{"id":"art-of-war_ch-11_p-5","chapterId":"art-of-war_ch-11","order":5,"canonicalText":"將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。若驅羣羊，驅而往，驅而來，莫知所之。聚三軍之眾，投之於險，此將軍之事也。九地之變，屈伸之利，人情之理，不可不察也。","sentenceIds":["art-of-war_ch-11_p-5_s-1","art-of-war_ch-11_p-5_s-2","art-of-war_ch-11_p-5_s-3","art-of-war_ch-11_p-5_s-4","art-of-war_ch-11_p-5_s-5","art-of-war_ch-11_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"將軍之事，靜以幽，正以治，能愚士去世之耳目，使之無知；易其事，革其謀，使人無識，易其居，迂其途，使人不得慮；帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機；若驅羣羊，驅而往，驅而來，莫知所之；聚三軍之眾，投之於險，此將軍之事也；九地之變，屈伸之利，人情之理，不可不察也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段論述了統帥的極致保密原則，以及如何強勢掌控軍隊的命運。\\n【詞義與名物】\\n靜以幽：沉著冷靜，深藏不露。愚士卒之耳目：矇蔽士兵，防止軍事機密洩露（古代將帥強調戰略層面的絕對保密）。去其梯：撤掉梯子，比喻切斷退路，置之死地。發其機：觸發弩機，比喻發動決定性打擊。\\n【兵家戰略】\\n在古代極端複雜的戰場環境中，孫子主張「愚兵」政策。這不是貶低士兵，而是為了防止情報洩露和軍心動搖。統帥必須像大腦一樣掌控絕對機密，將士兵視為純粹的執行力量（如驅羣羊）。透過刻意製造危機（去其梯），強行激發部隊的戰鬥力。"}},{"id":"art-of-war_ch-11_p-6","chapterId":"art-of-war_ch-11","order":6,"canonicalText":"凡為客之道，深則專，淺則散；去國越境而師者，絕地也；四達者，衢地也；入深者，重地也；入淺者，輕地也；背固前隘者，圍地也；無所往者，死地也。是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活。故兵之情，圍則禦，不得已則鬥，逼則從。","sentenceIds":["art-of-war_ch-11_p-6_s-1","art-of-war_ch-11_p-6_s-2","art-of-war_ch-11_p-6_s-3","art-of-war_ch-11_p-6_s-4","art-of-war_ch-11_p-6_s-5","art-of-war_ch-11_p-6_s-6","art-of-war_ch-11_p-6_s-7","art-of-war_ch-11_p-6_s-8","art-of-war_ch-11_p-6_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"凡為客之道，深則專，淺則散；去國越境而師者，絕地也；四達者，衢地也；入深者，重地也；入淺者，輕地也；背固前隘者，圍地也；無所往者，死地也；是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活；故兵之情，圍則禦，不得已則鬥，逼則從。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段再次回顧並深化了「九地」的戰術應對方法，重點強調針對不同地形採取相應的統御手段。\\n【詞義與名物】\\n一其志：統一意志，防止渙散。使之屬：使部隊互相聯繫、首尾相接。塞其闕：堵住缺口，斷絕退路。示之以不活：展示必死之心，不留活路。\\n【兵家戰略】\\n孫子將地理學與心理學完美結合。將領不僅要適應地形的物理特徵（如重地繼食，圮地進途），更要利用地形對士兵心理的影響來實施控制。特別是在圍地和死地，統帥要主動斷絕退路（塞其闕、示之以不活），利用人類在極限恐懼下的爆發力來換取勝利。"}},{"id":"art-of-war_ch-11_p-7","chapterId":"art-of-war_ch-11","order":7,"canonicalText":"是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也。夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合。是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮。施無法之賞，懸無政之令，犯三軍之眾，若使一人。犯之以事，勿告以言；犯之以利，勿告以害；投之亡地然後存，陷之死地然後生。夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。","sentenceIds":["art-of-war_ch-11_p-7_s-1","art-of-war_ch-11_p-7_s-2","art-of-war_ch-11_p-7_s-3","art-of-war_ch-11_p-7_s-4","art-of-war_ch-11_p-7_s-5","art-of-war_ch-11_p-7_s-6","art-of-war_ch-11_p-7_s-7","art-of-war_ch-11_p-7_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也；夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合；是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮；施無法之賞，懸無政之令，犯三軍之眾，若使一人；犯之以事，勿告以言；犯之以利，勿告以害；投之亡地然後存，陷之死地然後生；夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈九地〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「是故不知諸侯之謀者，不能預交，不知山……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-11_p-8","chapterId":"art-of-war_ch-11","order":8,"canonicalText":"是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。先其所愛，微與之期，賤墨隨敵，以決戰爭。是故始如處女，敵人開戶，後如脫兔，敵不及拒。","sentenceIds":["art-of-war_ch-11_p-8_s-1","art-of-war_ch-11_p-8_s-2","art-of-war_ch-11_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之；先其所愛，微與之期，賤墨隨敵，以決戰爭；是故始如處女，敵人開戶，後如脫兔，敵不及拒。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段總結了戰爭爆發前夕的戰備措施，以及開戰後的戰術指導原則。\\n【詞義與名物】\\n夷關折符：封鎖關口，廢棄通行憑證。厲於廊廟：在朝堂上嚴肅商討。開闔：出現空隙、漏洞。賤墨：摒棄刻板的規矩和教條（墨指繩墨、法度）。始如處女，後如脫兔：比喻先示弱以麻痺敵人，後迅猛出擊。\\n【兵家戰略】\\n備戰必須絕對保密（夷關折符），決策必須慎重（厲於廊廟）。但在實戰中，則必須拋棄一切教條（賤墨隨敵）。「始如處女，後如脫兔」是極其形象的戰術總結：極致的偽裝與極致的速度相結合，讓敵人在麻痺大意中遭遇毀滅性打擊。"}},{"id":"art-of-war_ch-12_p-1","chapterId":"art-of-war_ch-12","order":1,"canonicalText":"孫子曰：凡火攻有五：一曰火人，二曰火積，三曰火輜，四曰火庫，五曰火隊。行火必有因，煙火必素具。發火有時，起火有日。時者，天之燥也。日者，月在箕壁翼軫也。凡此四宿者，風起之日也。","sentenceIds":["art-of-war_ch-12_p-1_s-1","art-of-war_ch-12_p-1_s-2","art-of-war_ch-12_p-1_s-3","art-of-war_ch-12_p-1_s-4","art-of-war_ch-12_p-1_s-5","art-of-war_ch-12_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：凡火攻有五：一說：火人，二說：火積，三說：火輜，四說：火庫，五說：火隊；行火必有因，煙火必素具；發火有時，起火有日；時者，天之燥也；日者，月在箕壁翼軫也；凡此四宿者，風起之日也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段出自《火攻篇》，論述了古代戰爭中大規模殺傷性武器——火攻的具體分類與氣象條件。\\n【詞義與名物】\\n火人、火積、火輜、火庫、火隊：火攻的五個主要目標（人員、糧草、裝備、軍庫、交通線）。宿：星宿，古代天文學名詞。箕、壁、翼、軫：二十八宿中的四個，古人認為這四星出現時多有大風。\\n【兵家戰略】\\n火攻具有巨大的破壞力，但極度依賴自然條件。孫子將天文氣象（燥、風）納入軍事戰術之中，強調戰爭需要精密的天文觀測和長期的物資準備（素具）。這展示了古代軍事家對自然力量的敬畏與科學利用。"}},{"id":"art-of-war_ch-12_p-2","chapterId":"art-of-war_ch-12","order":2,"canonicalText":"凡火攻，必因五火之變而應之，火發於內，則早應之於外。火發而其兵靜者，待而勿攻。極其火力，可從而從之，不可從而止。火可發於外，無待於內，以時發之。火發上風，無攻下風，晝風久，夜風止。凡軍必知五火之變，以數守之。故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。","sentenceIds":["art-of-war_ch-12_p-2_s-1","art-of-war_ch-12_p-2_s-2","art-of-war_ch-12_p-2_s-3","art-of-war_ch-12_p-2_s-4","art-of-war_ch-12_p-2_s-5","art-of-war_ch-12_p-2_s-6","art-of-war_ch-12_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"凡火攻，必因五火之變而應之，火發於內，則早應之於外；火發而其兵靜者，待而勿攻；極其火力，可從而從之，不可從而止；火可發於外，無待於內，以時發之；火發上風，無攻下風，晝風久，夜風止；凡軍必知五火之變，以數守之；故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《孫子兵法》〈火攻〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「凡火攻，必因」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"art-of-war_ch-12_p-3","chapterId":"art-of-war_ch-12","order":3,"canonicalText":"夫戰勝攻取，而不修其攻者兇，命曰費留。故曰：明主慮之，良將修之，非利不動，非得不用，非危不戰。主不可以怒而興師，將不可以慍而致戰；合於利而動，不合於利而止。怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生。故明君慎之，良將警之，此安國全軍之道也。","sentenceIds":["art-of-war_ch-12_p-3_s-1","art-of-war_ch-12_p-3_s-2","art-of-war_ch-12_p-3_s-3","art-of-war_ch-12_p-3_s-4","art-of-war_ch-12_p-3_s-5","art-of-war_ch-12_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"夫戰勝攻取，而不修其攻者兇，命說：費留；故說：明主慮之，良將修之，非利不動，非得不用，非危不戰；主不可以怒而興師，將不可以慍而致戰；合於利而動，不合於利而止；怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生；故明君慎之，良將警之，此安國全軍之道也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段從火攻的毀滅性引申到戰爭的殘酷性，發出了全書最為深刻的慎戰警告。\\n【詞義與名物】\\n修其攻：鞏固戰果，治理攻佔之地。費留：空耗人力物力，白費力氣。慍：怨恨。\\n【兵家戰略】\\n孫子的戰爭觀極端冷靜且務實。他嚴厲警告君王和將領，絕對不能讓個人情緒（怒、慍）綁架國家戰略。戰爭的唯一目的是「利」。生命和國家是不可逆的（亡國不可復存，死者不可復生），這種深刻的悲憫與理智，將《孫子兵法》從一部純粹的軍事技術手冊，昇華為一部偉大的政治哲學著作。"}},{"id":"art-of-war_ch-13_p-1","chapterId":"art-of-war_ch-13","order":1,"canonicalText":"孫子曰：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也。故明君賢將，所以動而勝人，成功出於眾者，先知也；先知者，不可取於鬼神，不可象於事，不可驗於度；必取於人，知敵之情者也。","sentenceIds":["art-of-war_ch-13_p-1_s-1","art-of-war_ch-13_p-1_s-2","art-of-war_ch-13_p-1_s-3","art-of-war_ch-13_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"孫孔子說：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也；故明君賢將，所以動而勝人，成功出於眾者，先知也；先知者，不可取於鬼神，不可象於事，不可驗於度；必取於人，知敵之情者也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈用間〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「孫子曰：凡興師十萬，出征千里，百姓之……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"art-of-war_ch-13_p-2","chapterId":"art-of-war_ch-13","order":2,"canonicalText":"故用間有五：有鄉間、有內間、有反間、有死間、有生間。五間俱起，莫知其道，是謂神紀，人君之寶也。鄉間者，因其鄉人而用之。內間者，因其官人而用之。反間者，因其敵間而用之。死間者，為誑事於外，令吾間知之，而傳於敵。生間者，反報也。","sentenceIds":["art-of-war_ch-13_p-2_s-1","art-of-war_ch-13_p-2_s-2","art-of-war_ch-13_p-2_s-3","art-of-war_ch-13_p-2_s-4","art-of-war_ch-13_p-2_s-5","art-of-war_ch-13_p-2_s-6","art-of-war_ch-13_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"故用間有五：有鄉間、有內間、有反間、有死間、有生間；五間俱起，莫知其道，是謂神紀，人君之寶也；鄉間者，因其鄉人而用之；內間者，因其官人而用之；反間者，因其敵間而用之；死間者，為誑事於外，令吾間知之，而傳於敵；生間者，反報也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段詳細分類了軍事間諜的五種類型，構建了中國古代最早、最完整的間諜體系。\\n【詞義與名物】\\n鄉間：利用敵國平民（草根情報網）。內間：敵國官員（高層內線）。反間：雙面間諜。死間：傳遞假情報並犧牲自己的間諜。生間：負責偵察並返回報告的間諜。神紀：神奇莫測的規律和法寶。\\n【兵家戰略】\\n「五間俱起」描繪了一個立體、多層次的情報網絡。從平民到高官，從雙面間諜到死間，涵蓋了情報收集、反間諜、戰略欺騙等多個維度。敵人面對這種全方位的情報滲透，將陷入徹底的瞎子與聾子狀態，這是現代情報戰思想的雛形。"}},{"id":"art-of-war_ch-13_p-3","chapterId":"art-of-war_ch-13","order":3,"canonicalText":"故三軍之事，親莫親於間，賞莫厚於間，事莫密於間，非聖智不能用間，非仁義不能使間，非微妙不能得間之實。微哉，微哉，無所不用間也。間事未發而先聞者，間與所告者皆死。","sentenceIds":["art-of-war_ch-13_p-3_s-1","art-of-war_ch-13_p-3_s-2","art-of-war_ch-13_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"因此，在軍隊的所有事務中，沒有什麼人比間諜更親信，沒有什麼賞賜比給間諜的更優厚，沒有什麼事情比間諜工作更機密。沒有超越常人的智慧就無法駕馭間諜，沒有仁義的手段就無法驅使間諜，沒有細緻入微的洞察力就無法辨別間諜情報的真偽。微妙啊，微妙啊！無時無處不可以使用間諜。如果間諜的機密計畫還沒開始實施就洩露了出去，那麼間諜和聽到這個機密的人都要被處死。","analysis":"【主題與背景】\\n本段論述了統帥對待情報工作的態度、手腕以及極端嚴格的保密紀律。\\n【詞義與名物】\\n親：親近、信任。厚：優厚。密：機密。聖智：極高的政治與軍事智慧。微妙：心思細密，能明辨真偽。\\n【兵家戰略】\\n情報工作是刀尖上的舞蹈。孫子提出情報管理的「三最」：最親信、最高薪、最機密。同時，間諜工作極其考驗領導者的素養，既要有感情投資（仁義），又要有識破反間諜的智慧（聖智、微妙）。洩密的殘酷處理方式（皆死），凸顯了情報戰的極端危險性。"}},{"id":"art-of-war_ch-13_p-4","chapterId":"art-of-war_ch-13","order":4,"canonicalText":"凡軍之所欲擊，城之所欲攻，人之所欲殺；必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之。必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也。因是而知之，故鄉間內間可得而使也；因是而知之，故死間為誑事，可使告敵；因是而知之，故生間可使如期。五間之事，主必知之，知之必在於反間，故反間不可不厚也。","sentenceIds":["art-of-war_ch-13_p-4_s-1","art-of-war_ch-13_p-4_s-2","art-of-war_ch-13_p-4_s-3","art-of-war_ch-13_p-4_s-4","art-of-war_ch-13_p-4_s-5","art-of-war_ch-13_p-4_s-6","art-of-war_ch-13_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"凡軍之所欲擊，城之所欲攻，人之所欲殺；必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之；必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也；因是而知之，故鄉間內間可得而使也；因是而知之，故死間為誑事，可使告敵；因是而知之，故生間可使如期；五間之事，主必知之，知之必在於反間，故反間不可不厚也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段論述了情報工作的具體實施步驟，並高度拔高了「反間」（雙面間諜）的核心地位。\\n【詞義與名物】\\n謁者：負責通報傳達的官吏。門者：守門官。舍人：親信、門客。導而舍之：引導他並妥善安置他。\\n【兵家戰略】\\n戰前進行精確的人脈情報摸底，是精準打擊的前提。更重要的是，孫子揭示了間諜系統運作的核心樞紐：「反間」。雙面間諜不僅能提供敵方的高級機密，還能協助我方發展鄉間、內間，並為死間提供欺騙敵人的途徑。這是一套邏輯嚴密、環環相扣的情報生態系統。"}},{"id":"art-of-war_ch-13_p-5","chapterId":"art-of-war_ch-13","order":5,"canonicalText":"昔殷之興也，伊摯在夏。周之興也，呂牙在殷。故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。","sentenceIds":["art-of-war_ch-13_p-5_s-1","art-of-war_ch-13_p-5_s-2","art-of-war_ch-13_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"}],"readingAid":{"translation":"昔殷之興也，伊摯在夏；周之興也，呂牙在殷；故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段以歷史事實總結全篇，將情報工作提升到國家興亡的戰略高度。\\n【詞義與名物】\\n殷：商朝。伊摯：即伊尹，商湯的名臣，曾潛伏夏朝。呂牙：即姜子牙，周文王、武王的名臣，曾潛伏商朝。上智：擁有極高智慧的人才。\\n【兵家戰略】\\n《孫子兵法》以情報戰作為全書的收尾，意義深遠。孫子以伊尹、姜子牙兩位開國元勳為例，說明間諜絕不是見不得光的下流勾當，而是需要最頂尖人才（上智）去執行的國家最高戰略行動。情報是軍事決策的靈魂（三軍之所恃而動），決定了國家的歷史命運。"}}],"sentences":[{"id":"art-of-war_ch-1_p-1_s-1","passageId":"art-of-war_ch-1_p-1","order":1,"canonicalText":"孫子曰：兵者，國之大事，死生之地，存亡之道，不可不察也。","chunks":[["孫子曰：兵者，國之大事，死生之地，存亡之道，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-2_s-1","passageId":"art-of-war_ch-1_p-2","order":1,"canonicalText":"故經之以五事，校之以計，而索其情，一曰道，二曰天，三曰地，四曰將，五曰法。","chunks":[["故經之以五事，校之以計，而索其情，一曰道，二曰天，三曰地，四曰將，五曰法。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-1","passageId":"art-of-war_ch-1_p-3","order":1,"canonicalText":"道者，令民與上同意也，可與之死，可與之生，而不畏危。","chunks":[["道者，令民與上同意也，可與之死，可與之生，而不畏危。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-2","passageId":"art-of-war_ch-1_p-3","order":2,"canonicalText":"天者，陰陽，寒暑，時制也。","chunks":[["天者，陰陽，寒暑，時制也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-3","passageId":"art-of-war_ch-1_p-3","order":3,"canonicalText":"地者，遠近，險易，廣狹，死生也。","chunks":[["地者，遠近，險易，廣狹，死生也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-4","passageId":"art-of-war_ch-1_p-3","order":4,"canonicalText":"將者，智，信，仁，勇，嚴也。","chunks":[["將者，智，信，仁，勇，嚴也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-5","passageId":"art-of-war_ch-1_p-3","order":5,"canonicalText":"法者，曲制，官道，主用也。","chunks":[["法者，曲制，官道，主用也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-6","passageId":"art-of-war_ch-1_p-3","order":6,"canonicalText":"凡此五者，將莫不聞，知之者勝，不知者不勝。","chunks":[["凡此五者，將莫不聞，知之者勝，不知者不勝。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-1","passageId":"art-of-war_ch-1_p-4","order":1,"canonicalText":"故校之以計，而索其情。","chunks":[["故校之以計，而索其情。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-2","passageId":"art-of-war_ch-1_p-4","order":2,"canonicalText":"曰：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士卒孰練，賞罰孰明，吾以此知勝負矣。","chunks":[["曰：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士卒孰練，賞罰孰明，吾以此知勝負矣。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-3","passageId":"art-of-war_ch-1_p-4","order":3,"canonicalText":"將聽吾計，用之必勝，留之；","chunks":[["將聽吾計，用之必勝，留之；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-4","passageId":"art-of-war_ch-1_p-4","order":4,"canonicalText":"將不聽吾計，用之必敗，去之。","chunks":[["將不聽吾計，用之必敗，去之。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-5_s-1","passageId":"art-of-war_ch-1_p-5","order":1,"canonicalText":"計利以聽，乃為之勢，以佐其外；","chunks":[["計利以聽，乃為之勢，以佐其外；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-5_s-2","passageId":"art-of-war_ch-1_p-5","order":2,"canonicalText":"勢者，因利而制權也。","chunks":[["勢者，因利而制權也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-1","passageId":"art-of-war_ch-1_p-6","order":1,"canonicalText":"兵者，詭道也。","chunks":[["兵者，詭道也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-2","passageId":"art-of-war_ch-1_p-6","order":2,"canonicalText":"故能而示之不能，用而示之不用，近而示之遠，遠而示之近。","chunks":[["故能而示之不能，用而示之不用，近而示之遠，遠而示之近。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-3","passageId":"art-of-war_ch-1_p-6","order":3,"canonicalText":"利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之。","chunks":[["利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-4","passageId":"art-of-war_ch-1_p-6","order":4,"canonicalText":"攻其無備，出其不意，此兵家之勝，不可先傳也。","chunks":[["攻其無備，出其不意，此兵家之勝，不可先傳也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-1","passageId":"art-of-war_ch-1_p-7","order":1,"canonicalText":"夫未戰而廟算勝者，得算多也；","chunks":[["夫未戰而廟算勝者，得算多也；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-2","passageId":"art-of-war_ch-1_p-7","order":2,"canonicalText":"未戰而廟算不勝者，得算少也；","chunks":[["未戰而廟算不勝者，得算少也；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-3","passageId":"art-of-war_ch-1_p-7","order":3,"canonicalText":"多算勝，少算不勝，而況於無算乎？","chunks":[["多算勝，少算不勝，而況於無算乎？","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-4","passageId":"art-of-war_ch-1_p-7","order":4,"canonicalText":"吾以此觀之，勝負見矣。","chunks":[["吾以此觀之，勝負見矣。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-1_s-1","passageId":"art-of-war_ch-2_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，馳車千駟，革車千乘，帶甲十萬；","chunks":[["孫子曰：凡用兵之法，馳車千駟，革車千乘，帶甲十萬；","zh-Hant"]]},{"id":"art-of-war_ch-2_p-1_s-2","passageId":"art-of-war_ch-2_p-1","order":2,"canonicalText":"千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。","chunks":[["千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-1","passageId":"art-of-war_ch-2_p-2","order":1,"canonicalText":"其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足。","chunks":[["其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-2","passageId":"art-of-war_ch-2_p-2","order":2,"canonicalText":"夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣！","chunks":[["夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣！","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-3","passageId":"art-of-war_ch-2_p-2","order":3,"canonicalText":"故兵聞拙速，未睹巧之久也；","chunks":[["故兵聞拙速，未睹巧之久也；","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-4","passageId":"art-of-war_ch-2_p-2","order":4,"canonicalText":"夫兵久而國利者，未之有也。","chunks":[["夫兵久而國利者，未之有也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-3_s-1","passageId":"art-of-war_ch-2_p-3","order":1,"canonicalText":"故不盡知用兵之害者，則不能盡知用兵之利也。","chunks":[["故不盡知用兵之害者，則不能盡知用兵之利也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-3_s-2","passageId":"art-of-war_ch-2_p-3","order":2,"canonicalText":"善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也。","chunks":[["善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-3_s-3","passageId":"art-of-war_ch-2_p-3","order":3,"canonicalText":"國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。","chunks":[["國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-4_s-1","passageId":"art-of-war_ch-2_p-4","order":1,"canonicalText":"故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石。","chunks":[["故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-4_s-2","passageId":"art-of-war_ch-2_p-4","order":2,"canonicalText":"故殺敵者怒也，取敵之利者貨也。","chunks":[["故殺敵者怒也，取敵之利者貨也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-4_s-3","passageId":"art-of-war_ch-2_p-4","order":3,"canonicalText":"故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，卒善而養之，是謂勝敵而益強。","chunks":[["故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，卒善而養之，是謂勝敵而益強。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-5_s-1","passageId":"art-of-war_ch-2_p-5","order":1,"canonicalText":"故兵貴勝，不貴久；","chunks":[["故兵貴勝，不貴久；","zh-Hant"]]},{"id":"art-of-war_ch-2_p-5_s-2","passageId":"art-of-war_ch-2_p-5","order":2,"canonicalText":"故知兵之將，民之司命，國家安危之主也。","chunks":[["故知兵之將，民之司命，國家安危之主也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-1","passageId":"art-of-war_ch-3_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，全國為上，破國次之；","chunks":[["孫子曰：凡用兵之法，全國為上，破國次之；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-2","passageId":"art-of-war_ch-3_p-1","order":2,"canonicalText":"全旅為上，破旅次之；","chunks":[["全旅為上，破旅次之；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-3","passageId":"art-of-war_ch-3_p-1","order":3,"canonicalText":"全卒為上，破卒次之；","chunks":[["全卒為上，破卒次之；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-4","passageId":"art-of-war_ch-3_p-1","order":4,"canonicalText":"全伍為上，破伍次之。","chunks":[["全伍為上，破伍次之。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-5","passageId":"art-of-war_ch-3_p-1","order":5,"canonicalText":"是故百戰百勝，非善之善者也；","chunks":[["是故百戰百勝，非善之善者也；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-6","passageId":"art-of-war_ch-3_p-1","order":6,"canonicalText":"不戰而屈人之兵，善之善者也。","chunks":[["不戰而屈人之兵，善之善者也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-1","passageId":"art-of-war_ch-3_p-2","order":1,"canonicalText":"故上兵伐謀，其次伐交，其次伐兵，其下攻城。","chunks":[["故上兵伐謀，其次伐交，其次伐兵，其下攻城。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-2","passageId":"art-of-war_ch-3_p-2","order":2,"canonicalText":"攻城之法，為不得已；","chunks":[["攻城之法，為不得已；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-3","passageId":"art-of-war_ch-3_p-2","order":3,"canonicalText":"修櫓轒轀，具器械，三月而後成；","chunks":[["修櫓轒轀，具器械，三月而後成；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-4","passageId":"art-of-war_ch-3_p-2","order":4,"canonicalText":"距闉，又三月而後已；","chunks":[["距闉，又三月而後已；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-5","passageId":"art-of-war_ch-3_p-2","order":5,"canonicalText":"將不勝其忿，而蟻附之，殺士卒三分之一，而城不拔者，此攻之災也。","chunks":[["將不勝其忿，而蟻附之，殺士卒三分之一，而城不拔者，此攻之災也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-1","passageId":"art-of-war_ch-3_p-3","order":1,"canonicalText":"故善用兵者，屈人之兵，而非戰也；","chunks":[["故善用兵者，屈人之兵，而非戰也；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-2","passageId":"art-of-war_ch-3_p-3","order":2,"canonicalText":"拔人之城，而非攻也；","chunks":[["拔人之城，而非攻也；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-3","passageId":"art-of-war_ch-3_p-3","order":3,"canonicalText":"毀人之國，而非久也。","chunks":[["毀人之國，而非久也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-4","passageId":"art-of-war_ch-3_p-3","order":4,"canonicalText":"必以全爭於天下，故兵不頓，利可全，此謀攻之法也。","chunks":[["必以全爭於天下，故兵不頓，利可全，此謀攻之法也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-5","passageId":"art-of-war_ch-3_p-3","order":5,"canonicalText":"故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之。","chunks":[["故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-6","passageId":"art-of-war_ch-3_p-3","order":6,"canonicalText":"故小敵之堅，大敵之擒也。","chunks":[["故小敵之堅，大敵之擒也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-1","passageId":"art-of-war_ch-3_p-4","order":1,"canonicalText":"夫將者，國之輔也，輔周則國必強，輔隙則國必弱。","chunks":[["夫將者，國之輔也，輔周則國必強，輔隙則國必弱。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-2","passageId":"art-of-war_ch-3_p-4","order":2,"canonicalText":"故軍之所以患於君者三：不知三軍之不可以進，而謂之進；","chunks":[["故軍之所以患於君者三：不知三軍之不可以進，而謂之進；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-3","passageId":"art-of-war_ch-3_p-4","order":3,"canonicalText":"不知三軍之不可以退，而謂之退；","chunks":[["不知三軍之不可以退，而謂之退；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-4","passageId":"art-of-war_ch-3_p-4","order":4,"canonicalText":"是謂縻軍。","chunks":[["是謂縻軍。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-5","passageId":"art-of-war_ch-3_p-4","order":5,"canonicalText":"不知三軍之事，而同三軍之政，則軍士惑矣。","chunks":[["不知三軍之事，而同三軍之政，則軍士惑矣。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-6","passageId":"art-of-war_ch-3_p-4","order":6,"canonicalText":"不知三軍之權，而同三軍之任，則軍士疑矣。","chunks":[["不知三軍之權，而同三軍之任，則軍士疑矣。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-7","passageId":"art-of-war_ch-3_p-4","order":7,"canonicalText":"三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。","chunks":[["三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-5_s-1","passageId":"art-of-war_ch-3_p-5","order":1,"canonicalText":"故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；","chunks":[["故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-5_s-2","passageId":"art-of-war_ch-3_p-5","order":2,"canonicalText":"此五者，知勝之道也。","chunks":[["此五者，知勝之道也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-6_s-1","passageId":"art-of-war_ch-3_p-6","order":1,"canonicalText":"故曰：知彼知己，百戰不殆；","chunks":[["故曰：知彼知己，百戰不殆；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-6_s-2","passageId":"art-of-war_ch-3_p-6","order":2,"canonicalText":"不知彼而知己，一勝一負；","chunks":[["不知彼而知己，一勝一負；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-6_s-3","passageId":"art-of-war_ch-3_p-6","order":3,"canonicalText":"不知彼，不知己，每戰必敗。","chunks":[["不知彼，不知己，每戰必敗。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-1_s-1","passageId":"art-of-war_ch-4_p-1","order":1,"canonicalText":"孫子曰：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵。","chunks":[["孫子曰：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-1_s-2","passageId":"art-of-war_ch-4_p-1","order":2,"canonicalText":"故善戰者，能為不可勝，不能使敵必可勝。","chunks":[["故善戰者，能為不可勝，不能使敵必可勝。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-1_s-3","passageId":"art-of-war_ch-4_p-1","order":3,"canonicalText":"故曰：勝可知，而不可為。","chunks":[["故曰：勝可知，而不可為。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-1","passageId":"art-of-war_ch-4_p-2","order":1,"canonicalText":"不可勝者，守也；","chunks":[["不可勝者，守也；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-2","passageId":"art-of-war_ch-4_p-2","order":2,"canonicalText":"可勝者，攻也。","chunks":[["可勝者，攻也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-3","passageId":"art-of-war_ch-4_p-2","order":3,"canonicalText":"守則不足，攻則有餘。","chunks":[["守則不足，攻則有餘。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-4","passageId":"art-of-war_ch-4_p-2","order":4,"canonicalText":"善守者，藏於九地之下；","chunks":[["善守者，藏於九地之下；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-5","passageId":"art-of-war_ch-4_p-2","order":5,"canonicalText":"善攻者，動於九天之上，故能自保而全勝也。","chunks":[["善攻者，動於九天之上，故能自保而全勝也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-1","passageId":"art-of-war_ch-4_p-3","order":1,"canonicalText":"見勝，不過眾人之所知，非善之善者也。","chunks":[["見勝，不過眾人之所知，非善之善者也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-2","passageId":"art-of-war_ch-4_p-3","order":2,"canonicalText":"戰勝，而天下曰善，非善之善者也。","chunks":[["戰勝，而天下曰善，非善之善者也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-3","passageId":"art-of-war_ch-4_p-3","order":3,"canonicalText":"故舉秋毫，不為多力；","chunks":[["故舉秋毫，不為多力；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-4","passageId":"art-of-war_ch-4_p-3","order":4,"canonicalText":"見日月，不為明目；","chunks":[["見日月，不為明目；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-5","passageId":"art-of-war_ch-4_p-3","order":5,"canonicalText":"聞雷霆，不為聰耳。","chunks":[["聞雷霆，不為聰耳。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-6","passageId":"art-of-war_ch-4_p-3","order":6,"canonicalText":"古之善戰者，勝於易勝者；","chunks":[["古之善戰者，勝於易勝者；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-7","passageId":"art-of-war_ch-4_p-3","order":7,"canonicalText":"故善戰者之勝也，無智名，無勇功。","chunks":[["故善戰者之勝也，無智名，無勇功。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-8","passageId":"art-of-war_ch-4_p-3","order":8,"canonicalText":"故其戰勝不忒，不忒者，其措必勝，勝已敗者也。","chunks":[["故其戰勝不忒，不忒者，其措必勝，勝已敗者也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-9","passageId":"art-of-war_ch-4_p-3","order":9,"canonicalText":"故善戰者，立於不敗之地，而不失敵之敗也。","chunks":[["故善戰者，立於不敗之地，而不失敵之敗也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-10","passageId":"art-of-war_ch-4_p-3","order":10,"canonicalText":"是故勝兵先勝，而後求戰；","chunks":[["是故勝兵先勝，而後求戰；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-11","passageId":"art-of-war_ch-4_p-3","order":11,"canonicalText":"敗兵先戰，而後求勝。","chunks":[["敗兵先戰，而後求勝。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-1","passageId":"art-of-war_ch-4_p-4","order":1,"canonicalText":"善用兵者，修道而保法，故能為勝敗之政。","chunks":[["善用兵者，修道而保法，故能為勝敗之政。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-2","passageId":"art-of-war_ch-4_p-4","order":2,"canonicalText":"兵法：「一曰度，二曰量，三曰數，四曰稱，五曰勝；","chunks":[["兵法：「一曰度，二曰量，三曰數，四曰稱，五曰勝；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-3","passageId":"art-of-war_ch-4_p-4","order":3,"canonicalText":"地生度，度生量，量生數，數生稱，稱生勝。","chunks":[["地生度，度生量，量生數，數生稱，稱生勝。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-4","passageId":"art-of-war_ch-4_p-4","order":4,"canonicalText":"」故勝兵若以鎰稱銖，敗兵若以銖稱鎰。","chunks":[["」故勝兵若以鎰稱銖，敗兵若以銖稱鎰。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-5","passageId":"art-of-war_ch-4_p-4","order":5,"canonicalText":"勝者之戰民也，若決積水於千仞之谿，形也。","chunks":[["勝者之戰民也，若決積水於千仞之谿，形也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-1","passageId":"art-of-war_ch-5_p-1","order":1,"canonicalText":"孫子曰：凡治眾如治寡，分數是也。","chunks":[["孫子曰：凡治眾如治寡，分數是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-2","passageId":"art-of-war_ch-5_p-1","order":2,"canonicalText":"鬥眾如鬥寡，形名是也。","chunks":[["鬥眾如鬥寡，形名是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-3","passageId":"art-of-war_ch-5_p-1","order":3,"canonicalText":"三軍之眾，可使必受敵而無敗者，奇正是也。","chunks":[["三軍之眾，可使必受敵而無敗者，奇正是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-4","passageId":"art-of-war_ch-5_p-1","order":4,"canonicalText":"兵之所加，如以碬投卵者，虛實是也。","chunks":[["兵之所加，如以碬投卵者，虛實是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-1","passageId":"art-of-war_ch-5_p-2","order":1,"canonicalText":"凡戰者，以正合，以奇勝。","chunks":[["凡戰者，以正合，以奇勝。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-2","passageId":"art-of-war_ch-5_p-2","order":2,"canonicalText":"故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；","chunks":[["故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-3","passageId":"art-of-war_ch-5_p-2","order":3,"canonicalText":"死而復生，四時是也。","chunks":[["死而復生，四時是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-4","passageId":"art-of-war_ch-5_p-2","order":4,"canonicalText":"聲不過五，五聲之變，不可勝聽也。","chunks":[["聲不過五，五聲之變，不可勝聽也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-5","passageId":"art-of-war_ch-5_p-2","order":5,"canonicalText":"色不過五，五色之變，不可勝觀也。","chunks":[["色不過五，五色之變，不可勝觀也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-6","passageId":"art-of-war_ch-5_p-2","order":6,"canonicalText":"味不過五，五味之變，不可勝嘗也。","chunks":[["味不過五，五味之變，不可勝嘗也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-7","passageId":"art-of-war_ch-5_p-2","order":7,"canonicalText":"戰勢不過奇正，奇正之變，不可勝窮也。","chunks":[["戰勢不過奇正，奇正之變，不可勝窮也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-8","passageId":"art-of-war_ch-5_p-2","order":8,"canonicalText":"奇正相生，如循環之無端，孰能窮之哉！","chunks":[["奇正相生，如循環之無端，孰能窮之哉！","zh-Hant"]]},{"id":"art-of-war_ch-5_p-3_s-1","passageId":"art-of-war_ch-5_p-3","order":1,"canonicalText":"激水之疾，至於漂石者，勢也。","chunks":[["激水之疾，至於漂石者，勢也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-3_s-2","passageId":"art-of-war_ch-5_p-3","order":2,"canonicalText":"鷙鳥之擊，至於毀折者，節也。","chunks":[["鷙鳥之擊，至於毀折者，節也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-3_s-3","passageId":"art-of-war_ch-5_p-3","order":3,"canonicalText":"是故善戰者，其勢險，其節短，勢如張弩，節如機發。","chunks":[["是故善戰者，其勢險，其節短，勢如張弩，節如機發。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-1","passageId":"art-of-war_ch-5_p-4","order":1,"canonicalText":"紛紛紜紜，鬥亂，而不可亂也。","chunks":[["紛紛紜紜，鬥亂，而不可亂也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-2","passageId":"art-of-war_ch-5_p-4","order":2,"canonicalText":"渾渾沌沌，形圓，而不可敗也。","chunks":[["渾渾沌沌，形圓，而不可敗也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-3","passageId":"art-of-war_ch-5_p-4","order":3,"canonicalText":"亂生於治，怯生於勇，弱生於強。","chunks":[["亂生於治，怯生於勇，弱生於強。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-4","passageId":"art-of-war_ch-5_p-4","order":4,"canonicalText":"治亂，數也。","chunks":[["治亂，數也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-5","passageId":"art-of-war_ch-5_p-4","order":5,"canonicalText":"勇怯，勢也。","chunks":[["勇怯，勢也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-6","passageId":"art-of-war_ch-5_p-4","order":6,"canonicalText":"強弱，形也。","chunks":[["強弱，形也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-7","passageId":"art-of-war_ch-5_p-4","order":7,"canonicalText":"故善動敵者，形之，敵必從之；","chunks":[["故善動敵者，形之，敵必從之；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-8","passageId":"art-of-war_ch-5_p-4","order":8,"canonicalText":"予之，敵必取之；","chunks":[["予之，敵必取之；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-9","passageId":"art-of-war_ch-5_p-4","order":9,"canonicalText":"以利動之，以實待之。","chunks":[["以利動之，以實待之。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-5_s-1","passageId":"art-of-war_ch-5_p-5","order":1,"canonicalText":"故善戰者，求之於勢，不責於人，故能擇人任勢；","chunks":[["故善戰者，求之於勢，不責於人，故能擇人任勢；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-5_s-2","passageId":"art-of-war_ch-5_p-5","order":2,"canonicalText":"任勢者，其戰人也，如轉木石，木石之性，安則靜，危則動，方則止，圓則行。","chunks":[["任勢者，其戰人也，如轉木石，木石之性，安則靜，危則動，方則止，圓則行。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-5_s-3","passageId":"art-of-war_ch-5_p-5","order":3,"canonicalText":"故善戰人之勢，如轉圓石於千仞之山者，勢也。","chunks":[["故善戰人之勢，如轉圓石於千仞之山者，勢也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-1","passageId":"art-of-war_ch-6_p-1","order":1,"canonicalText":"孫子曰：凡先處戰地而待敵者佚，後處戰地而趨戰者勞。","chunks":[["孫子曰：凡先處戰地而待敵者佚，後處戰地而趨戰者勞。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-2","passageId":"art-of-war_ch-6_p-1","order":2,"canonicalText":"故善戰者，致人而不致於人。","chunks":[["故善戰者，致人而不致於人。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-3","passageId":"art-of-war_ch-6_p-1","order":3,"canonicalText":"能使敵人自至者，利之也；","chunks":[["能使敵人自至者，利之也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-4","passageId":"art-of-war_ch-6_p-1","order":4,"canonicalText":"能使敵不得至者，害之也。","chunks":[["能使敵不得至者，害之也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-5","passageId":"art-of-war_ch-6_p-1","order":5,"canonicalText":"故敵佚能勞之，飽能飢之，安能動之。","chunks":[["故敵佚能勞之，飽能飢之，安能動之。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-1","passageId":"art-of-war_ch-6_p-2","order":1,"canonicalText":"出其所不趨，趨其所不意；","chunks":[["出其所不趨，趨其所不意；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-2","passageId":"art-of-war_ch-6_p-2","order":2,"canonicalText":"行千里而不勞者，行於無人之地也；","chunks":[["行千里而不勞者，行於無人之地也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-3","passageId":"art-of-war_ch-6_p-2","order":3,"canonicalText":"攻而必取者，攻其所不守也；","chunks":[["攻而必取者，攻其所不守也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-4","passageId":"art-of-war_ch-6_p-2","order":4,"canonicalText":"守而必固者，守其所不攻也。","chunks":[["守而必固者，守其所不攻也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-5","passageId":"art-of-war_ch-6_p-2","order":5,"canonicalText":"故善攻者，敵不知其所守；","chunks":[["故善攻者，敵不知其所守；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-6","passageId":"art-of-war_ch-6_p-2","order":6,"canonicalText":"善守者，敵不知其所攻。","chunks":[["善守者，敵不知其所攻。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-7","passageId":"art-of-war_ch-6_p-2","order":7,"canonicalText":"微乎微乎！","chunks":[["微乎微乎！","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-8","passageId":"art-of-war_ch-6_p-2","order":8,"canonicalText":"至於無形；","chunks":[["至於無形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-9","passageId":"art-of-war_ch-6_p-2","order":9,"canonicalText":"神乎神乎！","chunks":[["神乎神乎！","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-10","passageId":"art-of-war_ch-6_p-2","order":10,"canonicalText":"至於無聲，故能為敵之司命。","chunks":[["至於無聲，故能為敵之司命。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-11","passageId":"art-of-war_ch-6_p-2","order":11,"canonicalText":"進而不可禦者，衝其虛也；","chunks":[["進而不可禦者，衝其虛也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-12","passageId":"art-of-war_ch-6_p-2","order":12,"canonicalText":"退而不可追者，速而不可及也。","chunks":[["退而不可追者，速而不可及也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-13","passageId":"art-of-war_ch-6_p-2","order":13,"canonicalText":"故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；","chunks":[["故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-14","passageId":"art-of-war_ch-6_p-2","order":14,"canonicalText":"我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。","chunks":[["我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-3_s-1","passageId":"art-of-war_ch-6_p-3","order":1,"canonicalText":"故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也。","chunks":[["故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-3_s-2","passageId":"art-of-war_ch-6_p-3","order":2,"canonicalText":"則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。","chunks":[["則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-1","passageId":"art-of-war_ch-6_p-4","order":1,"canonicalText":"吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣。","chunks":[["吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-2","passageId":"art-of-war_ch-6_p-4","order":2,"canonicalText":"故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡。","chunks":[["故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-3","passageId":"art-of-war_ch-6_p-4","order":3,"canonicalText":"寡者，備人者也；","chunks":[["寡者，備人者也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-4","passageId":"art-of-war_ch-6_p-4","order":4,"canonicalText":"眾者，使人備己者也。","chunks":[["眾者，使人備己者也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-1","passageId":"art-of-war_ch-6_p-5","order":1,"canonicalText":"故知戰之地，知戰之日，則可千里而會戰。","chunks":[["故知戰之地，知戰之日，則可千里而會戰。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-2","passageId":"art-of-war_ch-6_p-5","order":2,"canonicalText":"不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裏乎？","chunks":[["不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裏乎？","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-3","passageId":"art-of-war_ch-6_p-5","order":3,"canonicalText":"以吾度之，越人之兵雖多，亦奚益於勝哉？","chunks":[["以吾度之，越人之兵雖多，亦奚益於勝哉？","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-4","passageId":"art-of-war_ch-6_p-5","order":4,"canonicalText":"故曰：勝可為也，敵雖眾，可使無鬥。","chunks":[["故曰：勝可為也，敵雖眾，可使無鬥。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-1","passageId":"art-of-war_ch-6_p-6","order":1,"canonicalText":"故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。","chunks":[["故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-2","passageId":"art-of-war_ch-6_p-6","order":2,"canonicalText":"故形兵之極，至於無形；","chunks":[["故形兵之極，至於無形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-3","passageId":"art-of-war_ch-6_p-6","order":3,"canonicalText":"無形，則深間不能窺，智者不能謀。","chunks":[["無形，則深間不能窺，智者不能謀。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-4","passageId":"art-of-war_ch-6_p-6","order":4,"canonicalText":"因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；","chunks":[["因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-5","passageId":"art-of-war_ch-6_p-6","order":5,"canonicalText":"故其戰勝不復，而應形於無窮。","chunks":[["故其戰勝不復，而應形於無窮。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-1","passageId":"art-of-war_ch-6_p-7","order":1,"canonicalText":"夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；","chunks":[["夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-2","passageId":"art-of-war_ch-6_p-7","order":2,"canonicalText":"水因地而制流，兵因敵而制勝。","chunks":[["水因地而制流，兵因敵而制勝。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-3","passageId":"art-of-war_ch-6_p-7","order":3,"canonicalText":"故兵無常勢，水無常形；","chunks":[["故兵無常勢，水無常形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-4","passageId":"art-of-war_ch-6_p-7","order":4,"canonicalText":"能因敵變化而取勝，謂之神。","chunks":[["能因敵變化而取勝，謂之神。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-5","passageId":"art-of-war_ch-6_p-7","order":5,"canonicalText":"故五行無常勝，四時無常位，日有短長，月有死生。","chunks":[["故五行無常勝，四時無常位，日有短長，月有死生。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-1","passageId":"art-of-war_ch-7_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾，交和而舍，莫難於軍爭。","chunks":[["孫子曰：凡用兵之法，將受命於君，合軍聚眾，交和而舍，莫難於軍爭。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-2","passageId":"art-of-war_ch-7_p-1","order":2,"canonicalText":"軍爭之難者，以迂為直，以患為利。","chunks":[["軍爭之難者，以迂為直，以患為利。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-3","passageId":"art-of-war_ch-7_p-1","order":3,"canonicalText":"故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也。","chunks":[["故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-4","passageId":"art-of-war_ch-7_p-1","order":4,"canonicalText":"故軍爭為利，軍爭為危。","chunks":[["故軍爭為利，軍爭為危。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-1","passageId":"art-of-war_ch-7_p-2","order":1,"canonicalText":"舉軍而爭利，則不及；","chunks":[["舉軍而爭利，則不及；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-2","passageId":"art-of-war_ch-7_p-2","order":2,"canonicalText":"委軍而爭利，則輜重捐。","chunks":[["委軍而爭利，則輜重捐。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-3","passageId":"art-of-war_ch-7_p-2","order":3,"canonicalText":"是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；","chunks":[["是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-4","passageId":"art-of-war_ch-7_p-2","order":4,"canonicalText":"五十里而爭利，則蹶上將軍，其法半至；","chunks":[["五十里而爭利，則蹶上將軍，其法半至；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-5","passageId":"art-of-war_ch-7_p-2","order":5,"canonicalText":"卅里而爭利，則三分之二至。","chunks":[["卅里而爭利，則三分之二至。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-6","passageId":"art-of-war_ch-7_p-2","order":6,"canonicalText":"是故軍無輜重則亡，無糧食則亡，無委積則亡。","chunks":[["是故軍無輜重則亡，無糧食則亡，無委積則亡。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-7","passageId":"art-of-war_ch-7_p-2","order":7,"canonicalText":"故不知諸侯之謀者，不能豫交；","chunks":[["故不知諸侯之謀者，不能豫交；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-8","passageId":"art-of-war_ch-7_p-2","order":8,"canonicalText":"不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。","chunks":[["不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-3_s-1","passageId":"art-of-war_ch-7_p-3","order":1,"canonicalText":"故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆。","chunks":[["故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-3_s-2","passageId":"art-of-war_ch-7_p-3","order":2,"canonicalText":"掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。","chunks":[["掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-1","passageId":"art-of-war_ch-7_p-4","order":1,"canonicalText":"軍政曰：「言不相聞，故為金鼓；","chunks":[["軍政曰：「言不相聞，故為金鼓；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-2","passageId":"art-of-war_ch-7_p-4","order":2,"canonicalText":"視不相見，故為旌旗。","chunks":[["視不相見，故為旌旗。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-3","passageId":"art-of-war_ch-7_p-4","order":3,"canonicalText":"」夫金鼓旌旗者，所以一人之耳目也；","chunks":[["」夫金鼓旌旗者，所以一人之耳目也；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-4","passageId":"art-of-war_ch-7_p-4","order":4,"canonicalText":"人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也。","chunks":[["人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-5","passageId":"art-of-war_ch-7_p-4","order":5,"canonicalText":"故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。","chunks":[["故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-1","passageId":"art-of-war_ch-7_p-5","order":1,"canonicalText":"故三軍可奪氣，將軍可奪心。","chunks":[["故三軍可奪氣，將軍可奪心。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-2","passageId":"art-of-war_ch-7_p-5","order":2,"canonicalText":"是故朝氣銳，晝氣惰，暮氣歸；","chunks":[["是故朝氣銳，晝氣惰，暮氣歸；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-3","passageId":"art-of-war_ch-7_p-5","order":3,"canonicalText":"故善用兵者，避其銳氣，擊其惰歸，此治氣者也。","chunks":[["故善用兵者，避其銳氣，擊其惰歸，此治氣者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-4","passageId":"art-of-war_ch-7_p-5","order":4,"canonicalText":"以治待亂，以靜待譁，此治心者也。","chunks":[["以治待亂，以靜待譁，此治心者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-5","passageId":"art-of-war_ch-7_p-5","order":5,"canonicalText":"以近待遠，以佚待勞，以飽待飢，此治力者也。","chunks":[["以近待遠，以佚待勞，以飽待飢，此治力者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-6_s-1","passageId":"art-of-war_ch-7_p-6","order":1,"canonicalText":"無邀正正之旗，勿擊堂堂之陣，此治變者也；","chunks":[["無邀正正之旗，勿擊堂堂之陣，此治變者也；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-6_s-2","passageId":"art-of-war_ch-7_p-6","order":2,"canonicalText":"故用兵之法，高陵勿向，背邱勿逆，佯北勿從，銳卒勿攻，餌兵勿食，歸師勿遏，圍師必闕，窮寇勿迫，此用兵之法也。","chunks":[["故用兵之法，高陵勿向，背邱勿逆，佯北勿從，銳卒勿攻，餌兵勿食，歸師勿遏，圍師必闕，窮寇勿迫，此用兵之法也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-1","passageId":"art-of-war_ch-8_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾；","chunks":[["孫子曰：凡用兵之法，將受命於君，合軍聚眾；","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-2","passageId":"art-of-war_ch-8_p-1","order":2,"canonicalText":"圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。","chunks":[["圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-3","passageId":"art-of-war_ch-8_p-1","order":3,"canonicalText":"故將通於九變之利者，知用兵矣。","chunks":[["故將通於九變之利者，知用兵矣。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-4","passageId":"art-of-war_ch-8_p-1","order":4,"canonicalText":"將不通於九變之利者，雖知地形，不能得地之利矣。","chunks":[["將不通於九變之利者，雖知地形，不能得地之利矣。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-5","passageId":"art-of-war_ch-8_p-1","order":5,"canonicalText":"治兵不知九變之術，雖知地利，不能得人之用矣。","chunks":[["治兵不知九變之術，雖知地利，不能得人之用矣。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-2_s-1","passageId":"art-of-war_ch-8_p-2","order":1,"canonicalText":"是故智者之慮，必雜於利害，雜於利而務可信也，雜於害而患可解也。","chunks":[["是故智者之慮，必雜於利害，雜於利而務可信也，雜於害而患可解也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-2_s-2","passageId":"art-of-war_ch-8_p-2","order":2,"canonicalText":"是故屈諸侯者以害，役諸侯者以業，趨諸侯者以利。","chunks":[["是故屈諸侯者以害，役諸侯者以業，趨諸侯者以利。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-3_s-1","passageId":"art-of-war_ch-8_p-3","order":1,"canonicalText":"故用兵之法，無恃其不來，恃吾有以待之；","chunks":[["故用兵之法，無恃其不來，恃吾有以待之；","zh-Hant"]]},{"id":"art-of-war_ch-8_p-3_s-2","passageId":"art-of-war_ch-8_p-3","order":2,"canonicalText":"無恃其不攻，恃吾有所不可攻也。","chunks":[["無恃其不攻，恃吾有所不可攻也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-4_s-1","passageId":"art-of-war_ch-8_p-4","order":1,"canonicalText":"故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；","chunks":[["故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；","zh-Hant"]]},{"id":"art-of-war_ch-8_p-4_s-2","passageId":"art-of-war_ch-8_p-4","order":2,"canonicalText":"凡此五危，將之過也，用兵之災也。","chunks":[["凡此五危，將之過也，用兵之災也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-4_s-3","passageId":"art-of-war_ch-8_p-4","order":3,"canonicalText":"覆軍殺將，必以五危，不可不察也。","chunks":[["覆軍殺將，必以五危，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-1","passageId":"art-of-war_ch-9_p-1","order":1,"canonicalText":"孫子曰：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也。","chunks":[["孫子曰：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-2","passageId":"art-of-war_ch-9_p-1","order":2,"canonicalText":"絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利。","chunks":[["絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-3","passageId":"art-of-war_ch-9_p-1","order":3,"canonicalText":"欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也。","chunks":[["欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-4","passageId":"art-of-war_ch-9_p-1","order":4,"canonicalText":"絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也。","chunks":[["絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-5","passageId":"art-of-war_ch-9_p-1","order":5,"canonicalText":"平陸處易，右背高，前死後生，此處平陸之軍也。","chunks":[["平陸處易，右背高，前死後生，此處平陸之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-6","passageId":"art-of-war_ch-9_p-1","order":6,"canonicalText":"凡此四軍之利，黃帝之所以勝四帝也。","chunks":[["凡此四軍之利，黃帝之所以勝四帝也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-1","passageId":"art-of-war_ch-9_p-2","order":1,"canonicalText":"凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝。","chunks":[["凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-2","passageId":"art-of-war_ch-9_p-2","order":2,"canonicalText":"邱陵隄防，必處其陽，而右背之，此兵之利，地之助也。","chunks":[["邱陵隄防，必處其陽，而右背之，此兵之利，地之助也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-3","passageId":"art-of-war_ch-9_p-2","order":3,"canonicalText":"上雨水沫至，欲涉者，待其定也。","chunks":[["上雨水沫至，欲涉者，待其定也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-4","passageId":"art-of-war_ch-9_p-2","order":4,"canonicalText":"凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；","chunks":[["凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-5","passageId":"art-of-war_ch-9_p-2","order":5,"canonicalText":"吾遠之，敵近之；","chunks":[["吾遠之，敵近之；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-6","passageId":"art-of-war_ch-9_p-2","order":6,"canonicalText":"吾迎之，敵背之。","chunks":[["吾迎之，敵背之。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-7","passageId":"art-of-war_ch-9_p-2","order":7,"canonicalText":"軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。","chunks":[["軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-1","passageId":"art-of-war_ch-9_p-3","order":1,"canonicalText":"敵近而靜者，恃其險也。","chunks":[["敵近而靜者，恃其險也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-2","passageId":"art-of-war_ch-9_p-3","order":2,"canonicalText":"遠而挑戰者，欲人之進也。","chunks":[["遠而挑戰者，欲人之進也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-3","passageId":"art-of-war_ch-9_p-3","order":3,"canonicalText":"其所居易者，利也。","chunks":[["其所居易者，利也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-4","passageId":"art-of-war_ch-9_p-3","order":4,"canonicalText":"眾樹動者，來也。","chunks":[["眾樹動者，來也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-5","passageId":"art-of-war_ch-9_p-3","order":5,"canonicalText":"眾草多障者，疑也。","chunks":[["眾草多障者，疑也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-6","passageId":"art-of-war_ch-9_p-3","order":6,"canonicalText":"鳥起者，伏也。","chunks":[["鳥起者，伏也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-7","passageId":"art-of-war_ch-9_p-3","order":7,"canonicalText":"獸駭者，覆也。","chunks":[["獸駭者，覆也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-8","passageId":"art-of-war_ch-9_p-3","order":8,"canonicalText":"塵：高而銳者，車來也；","chunks":[["塵：高而銳者，車來也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-9","passageId":"art-of-war_ch-9_p-3","order":9,"canonicalText":"卑而廣者，徒來也；","chunks":[["卑而廣者，徒來也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-10","passageId":"art-of-war_ch-9_p-3","order":10,"canonicalText":"散而條違者，樵採也；","chunks":[["散而條違者，樵採也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-11","passageId":"art-of-war_ch-9_p-3","order":11,"canonicalText":"少而往來者，營軍也。","chunks":[["少而往來者，營軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-12","passageId":"art-of-war_ch-9_p-3","order":12,"canonicalText":"辭卑而益備者，進也。","chunks":[["辭卑而益備者，進也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-13","passageId":"art-of-war_ch-9_p-3","order":13,"canonicalText":"辭強而進驅者，退也。","chunks":[["辭強而進驅者，退也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-14","passageId":"art-of-war_ch-9_p-3","order":14,"canonicalText":"輕車先出其側者，陣也。","chunks":[["輕車先出其側者，陣也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-15","passageId":"art-of-war_ch-9_p-3","order":15,"canonicalText":"無約而請和者，謀也。","chunks":[["無約而請和者，謀也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-16","passageId":"art-of-war_ch-9_p-3","order":16,"canonicalText":"奔走而陳兵者，期也。","chunks":[["奔走而陳兵者，期也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-17","passageId":"art-of-war_ch-9_p-3","order":17,"canonicalText":"半進半退者，誘也。","chunks":[["半進半退者，誘也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-18","passageId":"art-of-war_ch-9_p-3","order":18,"canonicalText":"仗而立者，飢也。","chunks":[["仗而立者，飢也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-19","passageId":"art-of-war_ch-9_p-3","order":19,"canonicalText":"汲而先飲者，渴也。","chunks":[["汲而先飲者，渴也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-20","passageId":"art-of-war_ch-9_p-3","order":20,"canonicalText":"見利而不進者，勞也。","chunks":[["見利而不進者，勞也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-21","passageId":"art-of-war_ch-9_p-3","order":21,"canonicalText":"鳥集者，虛也。","chunks":[["鳥集者，虛也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-22","passageId":"art-of-war_ch-9_p-3","order":22,"canonicalText":"夜呼者，恐也。","chunks":[["夜呼者，恐也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-23","passageId":"art-of-war_ch-9_p-3","order":23,"canonicalText":"軍擾者，將不重也。","chunks":[["軍擾者，將不重也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-24","passageId":"art-of-war_ch-9_p-3","order":24,"canonicalText":"旌旗動者，亂也。","chunks":[["旌旗動者，亂也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-25","passageId":"art-of-war_ch-9_p-3","order":25,"canonicalText":"吏怒者，倦也。","chunks":[["吏怒者，倦也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-26","passageId":"art-of-war_ch-9_p-3","order":26,"canonicalText":"殺馬肉食者，軍無糧也。","chunks":[["殺馬肉食者，軍無糧也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-27","passageId":"art-of-war_ch-9_p-3","order":27,"canonicalText":"懸缶不返其舍者，窮寇也。","chunks":[["懸缶不返其舍者，窮寇也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-28","passageId":"art-of-war_ch-9_p-3","order":28,"canonicalText":"諄諄翕翕，徐與人言者，失眾也。","chunks":[["諄諄翕翕，徐與人言者，失眾也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-29","passageId":"art-of-war_ch-9_p-3","order":29,"canonicalText":"數賞者，窘也。","chunks":[["數賞者，窘也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-30","passageId":"art-of-war_ch-9_p-3","order":30,"canonicalText":"數罰者，困也。","chunks":[["數罰者，困也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-31","passageId":"art-of-war_ch-9_p-3","order":31,"canonicalText":"先暴而後畏其眾者，不精之至也。","chunks":[["先暴而後畏其眾者，不精之至也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-32","passageId":"art-of-war_ch-9_p-3","order":32,"canonicalText":"來委謝者，欲休息也。","chunks":[["來委謝者，欲休息也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-33","passageId":"art-of-war_ch-9_p-3","order":33,"canonicalText":"兵怒而相迎，久而不合，又不相去，必謹察之。","chunks":[["兵怒而相迎，久而不合，又不相去，必謹察之。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-4_s-1","passageId":"art-of-war_ch-9_p-4","order":1,"canonicalText":"兵非貴益多，惟無武進，足以併力料敵取人而已。","chunks":[["兵非貴益多，惟無武進，足以併力料敵取人而已。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-4_s-2","passageId":"art-of-war_ch-9_p-4","order":2,"canonicalText":"夫惟無慮而易敵者，必擒於人。","chunks":[["夫惟無慮而易敵者，必擒於人。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-1","passageId":"art-of-war_ch-9_p-5","order":1,"canonicalText":"卒未親附而罰之，則不服，不服則難用。","chunks":[["卒未親附而罰之，則不服，不服則難用。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-2","passageId":"art-of-war_ch-9_p-5","order":2,"canonicalText":"卒已親附而罰不行，則不可用。","chunks":[["卒已親附而罰不行，則不可用。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-3","passageId":"art-of-war_ch-9_p-5","order":3,"canonicalText":"故令之以文，齊之以武，是謂必取。","chunks":[["故令之以文，齊之以武，是謂必取。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-4","passageId":"art-of-war_ch-9_p-5","order":4,"canonicalText":"令素行以教其民，則民服；","chunks":[["令素行以教其民，則民服；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-5","passageId":"art-of-war_ch-9_p-5","order":5,"canonicalText":"令不素行以教其民，則民不服；","chunks":[["令不素行以教其民，則民不服；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-6","passageId":"art-of-war_ch-9_p-5","order":6,"canonicalText":"令素行，與眾相得也。","chunks":[["令素行，與眾相得也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-1","passageId":"art-of-war_ch-10_p-1","order":1,"canonicalText":"孫子曰：地形有通者，有掛者，有支者，有隘者，有險者，有遠者。","chunks":[["孫子曰：地形有通者，有掛者，有支者，有隘者，有險者，有遠者。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-2","passageId":"art-of-war_ch-10_p-1","order":2,"canonicalText":"我可以往，彼可以來，曰通；","chunks":[["我可以往，彼可以來，曰通；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-3","passageId":"art-of-war_ch-10_p-1","order":3,"canonicalText":"通形者，先居高陽，利糧道以戰，則利。","chunks":[["通形者，先居高陽，利糧道以戰，則利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-4","passageId":"art-of-war_ch-10_p-1","order":4,"canonicalText":"可以往，難以返，曰掛；","chunks":[["可以往，難以返，曰掛；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-5","passageId":"art-of-war_ch-10_p-1","order":5,"canonicalText":"掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利。","chunks":[["掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-6","passageId":"art-of-war_ch-10_p-1","order":6,"canonicalText":"我出而不利，彼出而不利，曰支；","chunks":[["我出而不利，彼出而不利，曰支；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-7","passageId":"art-of-war_ch-10_p-1","order":7,"canonicalText":"支形者，敵雖利我，我無出也；","chunks":[["支形者，敵雖利我，我無出也；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-8","passageId":"art-of-war_ch-10_p-1","order":8,"canonicalText":"引而去之，令敵半出而擊之，利。","chunks":[["引而去之，令敵半出而擊之，利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-9","passageId":"art-of-war_ch-10_p-1","order":9,"canonicalText":"隘形者，我先居之，必盈以待敵；","chunks":[["隘形者，我先居之，必盈以待敵；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-10","passageId":"art-of-war_ch-10_p-1","order":10,"canonicalText":"若敵先居之，盈而勿從，不盈而從之。","chunks":[["若敵先居之，盈而勿從，不盈而從之。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-11","passageId":"art-of-war_ch-10_p-1","order":11,"canonicalText":"險形者，我先居之，必居高陽以待敵；","chunks":[["險形者，我先居之，必居高陽以待敵；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-12","passageId":"art-of-war_ch-10_p-1","order":12,"canonicalText":"若敵先居之，引而去之，勿從也。","chunks":[["若敵先居之，引而去之，勿從也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-13","passageId":"art-of-war_ch-10_p-1","order":13,"canonicalText":"遠形者，勢均，難以挑戰，戰而不利。","chunks":[["遠形者，勢均，難以挑戰，戰而不利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-14","passageId":"art-of-war_ch-10_p-1","order":14,"canonicalText":"凡此六者，地之道也，將之至任，不可不察也。","chunks":[["凡此六者，地之道也，將之至任，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-1","passageId":"art-of-war_ch-10_p-2","order":1,"canonicalText":"故兵有走者，有弛者，有陷者，有崩者，有亂者，有北者；","chunks":[["故兵有走者，有弛者，有陷者，有崩者，有亂者，有北者；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-2","passageId":"art-of-war_ch-10_p-2","order":2,"canonicalText":"凡此六者，非天地之災，將之過也。","chunks":[["凡此六者，非天地之災，將之過也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-3","passageId":"art-of-war_ch-10_p-2","order":3,"canonicalText":"夫勢均，以一擊十，曰走。","chunks":[["夫勢均，以一擊十，曰走。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-4","passageId":"art-of-war_ch-10_p-2","order":4,"canonicalText":"卒強吏弱，曰弛。","chunks":[["卒強吏弱，曰弛。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-5","passageId":"art-of-war_ch-10_p-2","order":5,"canonicalText":"吏強卒弱，曰陷。","chunks":[["吏強卒弱，曰陷。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-6","passageId":"art-of-war_ch-10_p-2","order":6,"canonicalText":"大吏怒而不服，遇敵懟而自戰，將不知其能，曰崩。","chunks":[["大吏怒而不服，遇敵懟而自戰，將不知其能，曰崩。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-7","passageId":"art-of-war_ch-10_p-2","order":7,"canonicalText":"將弱不嚴，教道不明，吏卒無常，陳兵縱橫，曰亂。","chunks":[["將弱不嚴，教道不明，吏卒無常，陳兵縱橫，曰亂。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-8","passageId":"art-of-war_ch-10_p-2","order":8,"canonicalText":"將不能料敵，以少合眾，以弱擊強，兵無選鋒，曰北。","chunks":[["將不能料敵，以少合眾，以弱擊強，兵無選鋒，曰北。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-9","passageId":"art-of-war_ch-10_p-2","order":9,"canonicalText":"凡此六者，敗之道也。","chunks":[["凡此六者，敗之道也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-10","passageId":"art-of-war_ch-10_p-2","order":10,"canonicalText":"將之至任，不可不察也。","chunks":[["將之至任，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-1","passageId":"art-of-war_ch-10_p-3","order":1,"canonicalText":"夫地形者，兵之助也。","chunks":[["夫地形者，兵之助也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-2","passageId":"art-of-war_ch-10_p-3","order":2,"canonicalText":"料敵制勝，計險阨遠近，上將之道也。","chunks":[["料敵制勝，計險阨遠近，上將之道也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-3","passageId":"art-of-war_ch-10_p-3","order":3,"canonicalText":"知此而用戰者，必勝；","chunks":[["知此而用戰者，必勝；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-4","passageId":"art-of-war_ch-10_p-3","order":4,"canonicalText":"不知此而用戰者必敗。","chunks":[["不知此而用戰者必敗。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-5","passageId":"art-of-war_ch-10_p-3","order":5,"canonicalText":"故戰道必勝；","chunks":[["故戰道必勝；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-6","passageId":"art-of-war_ch-10_p-3","order":6,"canonicalText":"主曰：無戰；","chunks":[["主曰：無戰；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-7","passageId":"art-of-war_ch-10_p-3","order":7,"canonicalText":"必戰可也。","chunks":[["必戰可也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-8","passageId":"art-of-war_ch-10_p-3","order":8,"canonicalText":"戰道不勝，主曰必戰，無戰可也。","chunks":[["戰道不勝，主曰必戰，無戰可也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-9","passageId":"art-of-war_ch-10_p-3","order":9,"canonicalText":"故進不求名，退不避罪，唯民是保，而利於主，國之寶也。","chunks":[["故進不求名，退不避罪，唯民是保，而利於主，國之寶也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-4_s-1","passageId":"art-of-war_ch-10_p-4","order":1,"canonicalText":"視卒如嬰兒，故可與之赴深谿；","chunks":[["視卒如嬰兒，故可與之赴深谿；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-4_s-2","passageId":"art-of-war_ch-10_p-4","order":2,"canonicalText":"視卒如愛子，故可與之俱死。","chunks":[["視卒如愛子，故可與之俱死。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-4_s-3","passageId":"art-of-war_ch-10_p-4","order":3,"canonicalText":"厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。","chunks":[["厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-1","passageId":"art-of-war_ch-10_p-5","order":1,"canonicalText":"知吾卒之可以擊，而不知敵之不可擊，勝之半也；","chunks":[["知吾卒之可以擊，而不知敵之不可擊，勝之半也；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-2","passageId":"art-of-war_ch-10_p-5","order":2,"canonicalText":"知敵之可擊，而不知吾卒之不可擊，勝之半也。","chunks":[["知敵之可擊，而不知吾卒之不可擊，勝之半也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-3","passageId":"art-of-war_ch-10_p-5","order":3,"canonicalText":"知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。","chunks":[["知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-4","passageId":"art-of-war_ch-10_p-5","order":4,"canonicalText":"故知兵者，動而不迷，舉而不窮。","chunks":[["故知兵者，動而不迷，舉而不窮。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-5","passageId":"art-of-war_ch-10_p-5","order":5,"canonicalText":"故曰：知彼知己，勝乃不殆；","chunks":[["故曰：知彼知己，勝乃不殆；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-6","passageId":"art-of-war_ch-10_p-5","order":6,"canonicalText":"知天知地，勝乃可全。","chunks":[["知天知地，勝乃可全。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-1","passageId":"art-of-war_ch-11_p-1","order":1,"canonicalText":"孫子曰：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地。","chunks":[["孫子曰：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-2","passageId":"art-of-war_ch-11_p-1","order":2,"canonicalText":"諸侯自戰其地者，為散地。","chunks":[["諸侯自戰其地者，為散地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-3","passageId":"art-of-war_ch-11_p-1","order":3,"canonicalText":"入人之地而不深者，為輕地。","chunks":[["入人之地而不深者，為輕地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-4","passageId":"art-of-war_ch-11_p-1","order":4,"canonicalText":"我得則利，彼得亦利者，為爭地。","chunks":[["我得則利，彼得亦利者，為爭地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-5","passageId":"art-of-war_ch-11_p-1","order":5,"canonicalText":"我可以往，彼可以來者，為交地。","chunks":[["我可以往，彼可以來者，為交地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-6","passageId":"art-of-war_ch-11_p-1","order":6,"canonicalText":"諸侯之地三屬，先至而得天下之眾者，為衢地。","chunks":[["諸侯之地三屬，先至而得天下之眾者，為衢地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-7","passageId":"art-of-war_ch-11_p-1","order":7,"canonicalText":"入人之地深，背城邑多者，為重地。","chunks":[["入人之地深，背城邑多者，為重地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-8","passageId":"art-of-war_ch-11_p-1","order":8,"canonicalText":"山林、險阻、沮澤，凡難行之道者，為圮地。","chunks":[["山林、險阻、沮澤，凡難行之道者，為圮地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-9","passageId":"art-of-war_ch-11_p-1","order":9,"canonicalText":"所由入者隘，所從歸者迂，彼寡可以擊吾之眾者，為圍地。","chunks":[["所由入者隘，所從歸者迂，彼寡可以擊吾之眾者，為圍地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-10","passageId":"art-of-war_ch-11_p-1","order":10,"canonicalText":"疾戰則存，不疾戰則亡者，為死地。","chunks":[["疾戰則存，不疾戰則亡者，為死地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-11","passageId":"art-of-war_ch-11_p-1","order":11,"canonicalText":"是故散地則無戰，輕地則無止，爭地則無攻，交地則無絕，衢地則合交，重地則掠，圮地則行，圍地則謀，死地則戰。","chunks":[["是故散地則無戰，輕地則無止，爭地則無攻，交地則無絕，衢地則合交，重地則掠，圮地則行，圍地則謀，死地則戰。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-1","passageId":"art-of-war_ch-11_p-2","order":1,"canonicalText":"古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，卒離而不集，兵合而不齊。","chunks":[["古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，卒離而不集，兵合而不齊。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-2","passageId":"art-of-war_ch-11_p-2","order":2,"canonicalText":"合於利而動，不合於利而止。","chunks":[["合於利而動，不合於利而止。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-3","passageId":"art-of-war_ch-11_p-2","order":3,"canonicalText":"敢問：「敵眾整而將來，待之若何？","chunks":[["敢問：「敵眾整而將來，待之若何？","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-4","passageId":"art-of-war_ch-11_p-2","order":4,"canonicalText":"」曰：「先奪其所愛，則聽矣；","chunks":[["」曰：「先奪其所愛，則聽矣；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-5","passageId":"art-of-war_ch-11_p-2","order":5,"canonicalText":"兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。","chunks":[["兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-6","passageId":"art-of-war_ch-11_p-2","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-1","passageId":"art-of-war_ch-11_p-3","order":1,"canonicalText":"凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力。","chunks":[["凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-2","passageId":"art-of-war_ch-11_p-3","order":2,"canonicalText":"兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥。","chunks":[["兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-3","passageId":"art-of-war_ch-11_p-3","order":3,"canonicalText":"是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之。","chunks":[["是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-4","passageId":"art-of-war_ch-11_p-3","order":4,"canonicalText":"吾士無餘財，非惡貨也；","chunks":[["吾士無餘財，非惡貨也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-5","passageId":"art-of-war_ch-11_p-3","order":5,"canonicalText":"無餘命，非惡壽也。","chunks":[["無餘命，非惡壽也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-6","passageId":"art-of-war_ch-11_p-3","order":6,"canonicalText":"令發之日，士卒坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。","chunks":[["令發之日，士卒坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-1","passageId":"art-of-war_ch-11_p-4","order":1,"canonicalText":"故善用兵者，譬如率然；","chunks":[["故善用兵者，譬如率然；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-2","passageId":"art-of-war_ch-11_p-4","order":2,"canonicalText":"率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至。","chunks":[["率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-3","passageId":"art-of-war_ch-11_p-4","order":3,"canonicalText":"敢問：「兵可使如率然乎？","chunks":[["敢問：「兵可使如率然乎？","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-4","passageId":"art-of-war_ch-11_p-4","order":4,"canonicalText":"」曰：「可。","chunks":[["」曰：「可。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-5","passageId":"art-of-war_ch-11_p-4","order":5,"canonicalText":"」夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手。","chunks":[["」夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-6","passageId":"art-of-war_ch-11_p-4","order":6,"canonicalText":"是故，方馬埋輪，未足恃也，齊勇若一，政之道也；","chunks":[["是故，方馬埋輪，未足恃也，齊勇若一，政之道也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-7","passageId":"art-of-war_ch-11_p-4","order":7,"canonicalText":"剛柔皆得，地之理也。","chunks":[["剛柔皆得，地之理也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-8","passageId":"art-of-war_ch-11_p-4","order":8,"canonicalText":"故善用兵者，攜手若使一人，不得已也。","chunks":[["故善用兵者，攜手若使一人，不得已也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-1","passageId":"art-of-war_ch-11_p-5","order":1,"canonicalText":"將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。","chunks":[["將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-2","passageId":"art-of-war_ch-11_p-5","order":2,"canonicalText":"易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。","chunks":[["易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-3","passageId":"art-of-war_ch-11_p-5","order":3,"canonicalText":"帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。","chunks":[["帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-4","passageId":"art-of-war_ch-11_p-5","order":4,"canonicalText":"若驅羣羊，驅而往，驅而來，莫知所之。","chunks":[["若驅羣羊，驅而往，驅而來，莫知所之。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-5","passageId":"art-of-war_ch-11_p-5","order":5,"canonicalText":"聚三軍之眾，投之於險，此將軍之事也。","chunks":[["聚三軍之眾，投之於險，此將軍之事也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-6","passageId":"art-of-war_ch-11_p-5","order":6,"canonicalText":"九地之變，屈伸之利，人情之理，不可不察也。","chunks":[["九地之變，屈伸之利，人情之理，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-1","passageId":"art-of-war_ch-11_p-6","order":1,"canonicalText":"凡為客之道，深則專，淺則散；","chunks":[["凡為客之道，深則專，淺則散；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-2","passageId":"art-of-war_ch-11_p-6","order":2,"canonicalText":"去國越境而師者，絕地也；","chunks":[["去國越境而師者，絕地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-3","passageId":"art-of-war_ch-11_p-6","order":3,"canonicalText":"四達者，衢地也；","chunks":[["四達者，衢地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-4","passageId":"art-of-war_ch-11_p-6","order":4,"canonicalText":"入深者，重地也；","chunks":[["入深者，重地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-5","passageId":"art-of-war_ch-11_p-6","order":5,"canonicalText":"入淺者，輕地也；","chunks":[["入淺者，輕地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-6","passageId":"art-of-war_ch-11_p-6","order":6,"canonicalText":"背固前隘者，圍地也；","chunks":[["背固前隘者，圍地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-7","passageId":"art-of-war_ch-11_p-6","order":7,"canonicalText":"無所往者，死地也。","chunks":[["無所往者，死地也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-8","passageId":"art-of-war_ch-11_p-6","order":8,"canonicalText":"是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活。","chunks":[["是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-9","passageId":"art-of-war_ch-11_p-6","order":9,"canonicalText":"故兵之情，圍則禦，不得已則鬥，逼則從。","chunks":[["故兵之情，圍則禦，不得已則鬥，逼則從。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-1","passageId":"art-of-war_ch-11_p-7","order":1,"canonicalText":"是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也。","chunks":[["是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-2","passageId":"art-of-war_ch-11_p-7","order":2,"canonicalText":"夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合。","chunks":[["夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-3","passageId":"art-of-war_ch-11_p-7","order":3,"canonicalText":"是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮。","chunks":[["是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-4","passageId":"art-of-war_ch-11_p-7","order":4,"canonicalText":"施無法之賞，懸無政之令，犯三軍之眾，若使一人。","chunks":[["施無法之賞，懸無政之令，犯三軍之眾，若使一人。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-5","passageId":"art-of-war_ch-11_p-7","order":5,"canonicalText":"犯之以事，勿告以言；","chunks":[["犯之以事，勿告以言；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-6","passageId":"art-of-war_ch-11_p-7","order":6,"canonicalText":"犯之以利，勿告以害；","chunks":[["犯之以利，勿告以害；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-7","passageId":"art-of-war_ch-11_p-7","order":7,"canonicalText":"投之亡地然後存，陷之死地然後生。","chunks":[["投之亡地然後存，陷之死地然後生。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-8","passageId":"art-of-war_ch-11_p-7","order":8,"canonicalText":"夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。","chunks":[["夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-8_s-1","passageId":"art-of-war_ch-11_p-8","order":1,"canonicalText":"是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。","chunks":[["是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-8_s-2","passageId":"art-of-war_ch-11_p-8","order":2,"canonicalText":"先其所愛，微與之期，賤墨隨敵，以決戰爭。","chunks":[["先其所愛，微與之期，賤墨隨敵，以決戰爭。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-8_s-3","passageId":"art-of-war_ch-11_p-8","order":3,"canonicalText":"是故始如處女，敵人開戶，後如脫兔，敵不及拒。","chunks":[["是故始如處女，敵人開戶，後如脫兔，敵不及拒。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-1","passageId":"art-of-war_ch-12_p-1","order":1,"canonicalText":"孫子曰：凡火攻有五：一曰火人，二曰火積，三曰火輜，四曰火庫，五曰火隊。","chunks":[["孫子曰：凡火攻有五：一曰火人，二曰火積，三曰火輜，四曰火庫，五曰火隊。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-2","passageId":"art-of-war_ch-12_p-1","order":2,"canonicalText":"行火必有因，煙火必素具。","chunks":[["行火必有因，煙火必素具。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-3","passageId":"art-of-war_ch-12_p-1","order":3,"canonicalText":"發火有時，起火有日。","chunks":[["發火有時，起火有日。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-4","passageId":"art-of-war_ch-12_p-1","order":4,"canonicalText":"時者，天之燥也。","chunks":[["時者，天之燥也。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-5","passageId":"art-of-war_ch-12_p-1","order":5,"canonicalText":"日者，月在箕壁翼軫也。","chunks":[["日者，月在箕壁翼軫也。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-6","passageId":"art-of-war_ch-12_p-1","order":6,"canonicalText":"凡此四宿者，風起之日也。","chunks":[["凡此四宿者，風起之日也。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-1","passageId":"art-of-war_ch-12_p-2","order":1,"canonicalText":"凡火攻，必因五火之變而應之，火發於內，則早應之於外。","chunks":[["凡火攻，必因五火之變而應之，火發於內，則早應之於外。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-2","passageId":"art-of-war_ch-12_p-2","order":2,"canonicalText":"火發而其兵靜者，待而勿攻。","chunks":[["火發而其兵靜者，待而勿攻。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-3","passageId":"art-of-war_ch-12_p-2","order":3,"canonicalText":"極其火力，可從而從之，不可從而止。","chunks":[["極其火力，可從而從之，不可從而止。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-4","passageId":"art-of-war_ch-12_p-2","order":4,"canonicalText":"火可發於外，無待於內，以時發之。","chunks":[["火可發於外，無待於內，以時發之。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-5","passageId":"art-of-war_ch-12_p-2","order":5,"canonicalText":"火發上風，無攻下風，晝風久，夜風止。","chunks":[["火發上風，無攻下風，晝風久，夜風止。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-6","passageId":"art-of-war_ch-12_p-2","order":6,"canonicalText":"凡軍必知五火之變，以數守之。","chunks":[["凡軍必知五火之變，以數守之。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-7","passageId":"art-of-war_ch-12_p-2","order":7,"canonicalText":"故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。","chunks":[["故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-1","passageId":"art-of-war_ch-12_p-3","order":1,"canonicalText":"夫戰勝攻取，而不修其攻者兇，命曰費留。","chunks":[["夫戰勝攻取，而不修其攻者兇，命曰費留。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-2","passageId":"art-of-war_ch-12_p-3","order":2,"canonicalText":"故曰：明主慮之，良將修之，非利不動，非得不用，非危不戰。","chunks":[["故曰：明主慮之，良將修之，非利不動，非得不用，非危不戰。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-3","passageId":"art-of-war_ch-12_p-3","order":3,"canonicalText":"主不可以怒而興師，將不可以慍而致戰；","chunks":[["主不可以怒而興師，將不可以慍而致戰；","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-4","passageId":"art-of-war_ch-12_p-3","order":4,"canonicalText":"合於利而動，不合於利而止。","chunks":[["合於利而動，不合於利而止。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-5","passageId":"art-of-war_ch-12_p-3","order":5,"canonicalText":"怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生。","chunks":[["怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-6","passageId":"art-of-war_ch-12_p-3","order":6,"canonicalText":"故明君慎之，良將警之，此安國全軍之道也。","chunks":[["故明君慎之，良將警之，此安國全軍之道也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-1","passageId":"art-of-war_ch-13_p-1","order":1,"canonicalText":"孫子曰：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也。","chunks":[["孫子曰：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-2","passageId":"art-of-war_ch-13_p-1","order":2,"canonicalText":"故明君賢將，所以動而勝人，成功出於眾者，先知也；","chunks":[["故明君賢將，所以動而勝人，成功出於眾者，先知也；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-3","passageId":"art-of-war_ch-13_p-1","order":3,"canonicalText":"先知者，不可取於鬼神，不可象於事，不可驗於度；","chunks":[["先知者，不可取於鬼神，不可象於事，不可驗於度；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-4","passageId":"art-of-war_ch-13_p-1","order":4,"canonicalText":"必取於人，知敵之情者也。","chunks":[["必取於人，知敵之情者也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-1","passageId":"art-of-war_ch-13_p-2","order":1,"canonicalText":"故用間有五：有鄉間、有內間、有反間、有死間、有生間。","chunks":[["故用間有五：有鄉間、有內間、有反間、有死間、有生間。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-2","passageId":"art-of-war_ch-13_p-2","order":2,"canonicalText":"五間俱起，莫知其道，是謂神紀，人君之寶也。","chunks":[["五間俱起，莫知其道，是謂神紀，人君之寶也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-3","passageId":"art-of-war_ch-13_p-2","order":3,"canonicalText":"鄉間者，因其鄉人而用之。","chunks":[["鄉間者，因其鄉人而用之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-4","passageId":"art-of-war_ch-13_p-2","order":4,"canonicalText":"內間者，因其官人而用之。","chunks":[["內間者，因其官人而用之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-5","passageId":"art-of-war_ch-13_p-2","order":5,"canonicalText":"反間者，因其敵間而用之。","chunks":[["反間者，因其敵間而用之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-6","passageId":"art-of-war_ch-13_p-2","order":6,"canonicalText":"死間者，為誑事於外，令吾間知之，而傳於敵。","chunks":[["死間者，為誑事於外，令吾間知之，而傳於敵。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-7","passageId":"art-of-war_ch-13_p-2","order":7,"canonicalText":"生間者，反報也。","chunks":[["生間者，反報也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-3_s-1","passageId":"art-of-war_ch-13_p-3","order":1,"canonicalText":"故三軍之事，親莫親於間，賞莫厚於間，事莫密於間，非聖智不能用間，非仁義不能使間，非微妙不能得間之實。","chunks":[["故三軍之事，親莫親於間，賞莫厚於間，事莫密於間，非聖智不能用間，非仁義不能使間，非微妙不能得間之實。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-3_s-2","passageId":"art-of-war_ch-13_p-3","order":2,"canonicalText":"微哉，微哉，無所不用間也。","chunks":[["微哉，微哉，無所不用間也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-3_s-3","passageId":"art-of-war_ch-13_p-3","order":3,"canonicalText":"間事未發而先聞者，間與所告者皆死。","chunks":[["間事未發而先聞者，間與所告者皆死。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-1","passageId":"art-of-war_ch-13_p-4","order":1,"canonicalText":"凡軍之所欲擊，城之所欲攻，人之所欲殺；","chunks":[["凡軍之所欲擊，城之所欲攻，人之所欲殺；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-2","passageId":"art-of-war_ch-13_p-4","order":2,"canonicalText":"必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之。","chunks":[["必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-3","passageId":"art-of-war_ch-13_p-4","order":3,"canonicalText":"必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也。","chunks":[["必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-4","passageId":"art-of-war_ch-13_p-4","order":4,"canonicalText":"因是而知之，故鄉間內間可得而使也；","chunks":[["因是而知之，故鄉間內間可得而使也；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-5","passageId":"art-of-war_ch-13_p-4","order":5,"canonicalText":"因是而知之，故死間為誑事，可使告敵；","chunks":[["因是而知之，故死間為誑事，可使告敵；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-6","passageId":"art-of-war_ch-13_p-4","order":6,"canonicalText":"因是而知之，故生間可使如期。","chunks":[["因是而知之，故生間可使如期。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-7","passageId":"art-of-war_ch-13_p-4","order":7,"canonicalText":"五間之事，主必知之，知之必在於反間，故反間不可不厚也。","chunks":[["五間之事，主必知之，知之必在於反間，故反間不可不厚也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-5_s-1","passageId":"art-of-war_ch-13_p-5","order":1,"canonicalText":"昔殷之興也，伊摯在夏。","chunks":[["昔殷之興也，伊摯在夏。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-5_s-2","passageId":"art-of-war_ch-13_p-5","order":2,"canonicalText":"周之興也，呂牙在殷。","chunks":[["周之興也，呂牙在殷。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-5_s-3","passageId":"art-of-war_ch-13_p-5","order":3,"canonicalText":"故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。","chunks":[["故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。","zh-Hant"]]}]}') as WorkBundle
